/* MODULE dl09 · Bước 7 Đo lường · Trình bày số cho sếp
   10 bài × 7 câu. Tập trung kỹ năng trình bày: kết luận trước, so sánh, làm tròn, biểu đồ, độ chắc chắn.
   Mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'dl09', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:dl09-01', skill:'comm', read:'6 phút', t:'Sếp chỉ có 2 phút: bạn nói câu nào đầu tiên?',
  situation:'Linh phụ trách marketing online cho một chuỗi trà sữa ở Hà Nội. Họp sáng thứ Hai, giám đốc hỏi: "Tháng 9 thế nào?". Linh mở đầu: "Dạ tháng này bên em chạy 3 chiến dịch, tổng chi 120 triệu, lượt hiển thị 2,4 triệu, CTR 1,8%…". Tới phút thứ hai, giám đốc ngắt lời: "Tóm lại tốt hay không tốt, em cần anh quyết gì?".',
  concept:{ name:'Kết luận trước, số sau',
    body:'Người nghe nhớ rõ nhất câu đầu tiên. Vì vậy câu mở là <b>kết luận</b> (tốt hay xấu so với mục tiêu) và <b>việc cần sếp quyết</b>, tức việc mà thiếu câu trả lời của sếp thì bạn không đi tiếp được. Sau đó mới đến hai, ba con số làm bằng chứng; chi tiết quy trình để dành khi được hỏi. Ngoại lệ: khi sếp chủ động xin diễn biến ("kể anh nghe"), hãy nói kết quả một câu rồi kể theo thời gian, vì người nghe đã tự chọn cách nghe.' },
  example:'Linh viết lại câu mở: "Tháng 9 đạt 110% mục tiêu đơn online, nhờ chiến dịch combo 2 ly. Em đề xuất giữ combo sang tháng 10, cần anh duyệt thêm 30 triệu." Bằng chứng theo sau: 1.320 đơn so với mục tiêu 1.200, chi phí mỗi đơn 91 nghìn, thấp hơn kế hoạch 100 nghìn. Toàn bộ chỉ mất 30 giây; phần CTR và lượt hiển thị để trong phụ lục.',
  takeaway:'Câu đầu tiên là kết luận và việc cần quyết; con số đến sau để chứng minh.',
  points:["Sếp quyết định bằng cách chọn: duyệt, đổi hướng hay chờ. Câu mở có kết luận và việc cần quyết cho họ khung lựa chọn ngay, nên phần sau nghe như bằng chứng.","Hai đến ba con số là đủ khi có kết quả so với mục tiêu và chi phí. Thêm nữa khiến sếp tự chọn số nào quan trọng, việc đó thuộc về người báo cáo.","Chi tiết để ở phụ lục vẫn có ích: khi sếp hỏi thêm, bạn mở đúng trang và chứng tỏ mình nắm việc. Sắp xếp theo mức quan trọng, không theo thứ tự đã làm."],
  counter:"Giả sử kết quả hụt mục tiêu vì một lỗi giao hàng của đối tác và sếp đang bực. Mở thẳng bằng xấu hay tốt có thể bị nghe như đổ lỗi, hoặc sếp ngắt vì thiếu bối cảnh. Dấu hiệu nhận ra: sếp hỏi chuyện gì đã xảy ra trước khi hỏi kết quả. Khi đó nói ngắn sự việc trong một câu, rồi vào kết luận và việc cần sếp quyết.",
  deeper:"Người làm nghề đánh đổi giữa tốc độ và độ tin cậy: câu mở gọn chỉ hiệu quả khi sếp tin con số bạn sắp đưa. Vì vậy họ xây lòng tin bằng việc báo cả tin xấu sớm và đúng. Tín hiệu nên theo là sếp có ngắt lời hỏi lại hay không: bị ngắt nghĩa là câu mở chưa trả lời câu họ cần. Khái niệm kề cận là báo cáo theo cấu trúc kim tự tháp. Phép kiểm tra trong tuần: viết câu mở cho kết quả tuần này, bấm giờ dưới 15 giây, và đọc cho một đồng nghiệp xem họ có nói lại đúng việc cần quyết không.",
  apply:'Lấy kết quả tuần gần nhất của bạn, viết một câu mở gồm: tốt hay xấu so với mục tiêu, và một việc cần người nghe quyết. Đọc to, bấm giờ dưới 15 giây.',
  mistakes:['Kể lại công việc theo thứ tự thời gian thay vì nói kết quả.','Mở đầu bằng chỉ số trung gian (hiển thị, CTR) mà sếp không dùng để quyết định.'],
  q:[
  { type:'mcq', stem:'Sếp hỏi "Tháng này thế nào?". Câu mở nào giúp sếp nắm tình hình nhanh nhất?',
    options:[{k:'a',t:'Đạt 110% mục tiêu đơn; em cần anh duyệt thêm ngân sách tháng tới'},{k:'b',t:'Tháng này bên em chạy 3 chiến dịch trên Facebook, TikTok và Zalo với tổng chi 120 triệu'},
             {k:'c',t:'Lượt hiển thị tăng mạnh lên 2,4 triệu, CTR đạt 1,8%'},{k:'d',t:'Để em chia sẻ màn hình dashboard cho anh xem từng chỉ số'}],
    answer:'a', why:{a:'Đúng. Kết luận so với mục tiêu và việc cần quyết nằm ngay câu đầu.',
      b:'Đây là mô tả công việc; sếp vẫn chưa biết kết quả tốt hay xấu.',
      c:'Chỉ số trung gian không trả lời được câu "có đạt mục tiêu kinh doanh không".',
      d:'Đưa cả dashboard là bắt sếp tự rút kết luận thay cho bạn.'} },
  { type:'mcq', stem:'Bạn có 5 phút báo cáo, kết quả hụt mục tiêu 15% và bạn cần sếp chọn giữa hai phương án. Bạn chọn cách sắp xếp bài nói nào?',
    options:[{k:'a',t:'Kể lại diễn biến từng tuần để sếp tự thấy vì sao hụt, rồi mới nêu hai phương án ở cuối'},{k:'b',t:'Nêu hai phương án trước, giấu con số hụt để sếp không mất tinh thần'},
             {k:'c',t:'Nói hụt 15%, lý do chính, rồi hai phương án và phương án bạn chọn'},{k:'d',t:'Gửi file số liệu trước, họp chỉ để trả lời câu hỏi của sếp'}],
    answer:'c', why:{a:'Đi theo thời gian khiến sếp chờ 4 phút mới biết cần quyết gì; dễ hết giờ trước khi tới phần quan trọng.',
      b:'Giấu kết quả làm mất lòng tin khi sếp phát hiện ra; phương án cũng không có ngữ cảnh.',
      c:'Đúng. Kết luận, nguyên nhân, lựa chọn, đề xuất: sếp có đủ thứ để quyết trong 5 phút.',
      d:'File số không thay được kết luận; sếp vẫn phải tự đọc và tự suy ra.'} },
  { type:'mcq', stem:'Sếp nói: "Kể anh nghe tháng này diễn ra thế nào, anh muốn hiểu cả quá trình." Bạn làm gì?',
    options:[{k:'a',t:'Nói kết quả trong một câu, rồi kể ba mốc chính theo thời gian, mỗi mốc kèm một con số'},{k:'b',t:'Vẫn chỉ nói kết luận và việc cần quyết, vì nguyên tắc là không kể diễn biến'},
             {k:'c',t:'Mở dashboard để sếp tự theo dõi diễn biến từng tuần, bạn chỉ trả lời khi được hỏi'},{k:'d',t:'Kể đủ từng tuần theo thứ tự, để kết quả cuối cùng nói sau cùng cho trọn câu chuyện'}],
    answer:'a', why:{a:'Đúng. Sếp đã xin diễn biến nên kể theo thời gian là hợp; kết quả một câu đầu giúp sếp biết mình đang nghe đi đến đâu.',
      b:'Nguyên tắc kết luận trước để phục vụ người nghe; khi người nghe xin bối cảnh mà bạn từ chối thì không còn phục vụ họ.',
      c:'Đẩy việc tự kể chuyện từ bảng số sang sếp; dashboard không nói điểm ngoặt nào quan trọng.',
      d:'Kể mà để kết quả ở cuối làm sếp nghe 4 phút không biết đang tốt hay xấu; dễ bị ngắt lời như trong tình huống mở bài.'} },
  { type:'mcq', stem:'Sếp mở file lên hỏi: "CPC tuần này tăng 30%, vì sao?". Bạn đã kiểm tra: đối thủ cùng đấu thầu từ khoá dịp lễ, và bạn muốn hạ giá thầu nhóm từ khoá rộng. Câu nào đúng thứ tự?',
    options:[{k:'a',t:'Em đã vào từng nhóm từ khoá, đối chiếu giá thầu từng ngày, thấy đối thủ đấu nhiều nên CPC tăng'},{k:'b',t:'CPC tăng chủ yếu do thị trường chứ không phải do đội em; chi tiết em gửi anh file sau'},
             {k:'c',t:'Để anh dễ theo dõi, em xin trình bày CPC từng ngày trong tuần trước rồi nêu nguyên nhân sau cùng'},{k:'d',t:'CPC tăng 30% vì đối thủ đấu thầu dịp lễ; em đề xuất hạ thầu nhóm từ rộng, cần anh duyệt'}],
    answer:'d', why:{a:'Nói quy trình kiểm tra trước, sếp phải chờ tới cuối mới biết nguyên nhân và việc cần quyết; chi tiết này để dành khi được hỏi sâu.',
      b:'Quy lỗi cho thị trường mà không có con số hay đề xuất: sếp vẫn không biết nên quyết gì, và nghe như bào chữa.',
      c:'Kể theo thời gian là thứ tự của người làm, không phải của người quyết; nguyên nhân ở cuối dễ bị ngắt lời giữa chừng.',
      d:'Đúng. Số và nguyên nhân trong một câu, rồi việc cần quyết; quy trình kiểm tra để dành nếu sếp hỏi sâu.'} },
  { type:'calc', stem:'Kế hoạch: 1.200 đơn, chi phí 100 nghìn mỗi đơn. Thực tế đơn vượt kế hoạch 8% nhưng chi phí mỗi đơn cao hơn kế hoạch 12%. Tổng chi vượt kế hoạch bao nhiêu phần trăm? (làm tròn số nguyên)',
    unit:'%', ans:21, tol:0.5, wrong:[[20,'SAI_TINH_TOAN'],[12,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Tổng chi kế hoạch = 1.200 × 100 nghìn = 120 triệu.','Thực tế: 1.296 đơn × 112 nghìn ≈ 145,2 triệu; vượt 25,2 ÷ 120 ≈ <b>21%</b>. Hai mức tăng nhân với nhau (1,08 × 1,12), không cộng.'] },
  { type:'mcq', stem:'Tình huống mới: sếp hỏi giữa hành lang "Livestream tối qua ổn không?". Bạn trả lời thế nào?',
    options:[{k:'a',t:'"Để em về tổng hợp đầy đủ rồi gửi anh báo cáo chi tiết sau nhé"'},{k:'b',t:'"Tối qua bên em lên sóng lúc 8 giờ, có 3 host, chạy 2 tiếng"'},
             {k:'c',t:'"Chưa đạt: 180 đơn so với mục tiêu 250, em đang xem lại khung giờ"'},{k:'d',t:'"Được anh ạ, mắt xem đông lắm, bình luận sôi nổi"'}],
    answer:'c', why:{a:'Hoãn trả lời khi đã có số là bỏ lỡ cơ hội; sếp cần cảm nhận nhanh ngay.',
      b:'Đây là diễn biến, không phải kết quả.',
      c:'Đúng. Kết luận, một con số so với mục tiêu, và việc đang làm — gói trong một câu.',
      d:'"Đông", "sôi nổi" là cảm nhận, không so với mục tiêu nên sếp không biết tốt hay xấu.'} },
  { type:'mcq', stem:'Kết quả tháng này lẫn lộn: đơn tăng nhưng chi phí mỗi đơn cũng tăng. Câu mở nào hợp lý nhất?',
    options:[{k:'a',t:'Chỉ nói đơn vượt mục tiêu, còn phần chi phí tăng thì để sếp tự hỏi nếu quan tâm'},{k:'b',t:'Đơn vượt mục tiêu 8% nhưng chi phí mỗi đơn cao hơn kế hoạch 12%; em đề xuất cắt kênh X'},
             {k:'c',t:'Nói lần lượt từng chỉ số, không kết luận vì kết quả lẫn lộn'},{k:'d',t:'Chỉ nói chi phí tăng để sếp thấy mình nghiêm túc'}],
    answer:'b', why:{a:'Giấu mặt xấu là mất uy tín khi sếp phát hiện.',
      b:'Đúng. Kết quả lẫn lộn thì kết luận cũng nêu cả hai mặt, kèm đề xuất xử lý.',
      c:'Lẫn lộn vẫn cần kết luận; không kết luận là đẩy việc suy nghĩ sang sếp.',
      d:'Chỉ nêu mặt xấu cũng lệch như chỉ nêu mặt tốt.'} },
  ]},

/* ------------------------------------------------------------------ 02 */
{ id:'B:dl09-02', skill:'comm', read:'6 phút', t:'Slide có 4 biểu đồ và 12 con số: sếp nhớ được gì?',
  situation:'Tuấn làm báo cáo quý cho một thương hiệu nước mắm bán trên sàn. Slide số 3 của anh có 4 biểu đồ (doanh thu, đơn, chi phí quảng cáo, đánh giá sao) và 12 con số in đậm. Tiêu đề slide là "Tổng quan quý 3". Sau buổi họp, sếp hỏi lại: "Quý này mình tăng hay giảm nhỉ?".',
  concept:{ name:'Một slide, một ý',
    body:'Mỗi slide chỉ nên chứng minh một ý, và ý đó viết thành <b>tiêu đề dạng câu</b> (có động từ, có kết luận), không phải nhãn chủ đề. Biểu đồ và con số bên dưới chỉ ở lại nếu chúng chứng minh câu tiêu đề. Nhiều ý thì tách thành nhiều slide. Mẹo kiểm tra: đọc liền các tiêu đề slide từ đầu đến cuối, nếu thành một câu chuyện đủ nghĩa thì bộ slide ổn.' },
  example:'Tuấn tách slide 3 thành hai. Slide A: "Doanh thu quý 3 tăng 18% nhờ đơn tăng, giá bán giữ nguyên" với một biểu đồ cột doanh thu theo tháng. Slide B: "Chi phí quảng cáo tăng nhanh hơn doanh thu, cần xem lại" với hai con số: chi phí tăng 35%, doanh thu tăng 18%. Đánh giá sao ổn định 4,8 nên chuyển xuống phụ lục. Từ 12 con số còn 4.',
  takeaway:'Tiêu đề slide là một câu kết luận; thứ gì không chứng minh câu đó thì bỏ ra.',
  points:["Tiêu đề dạng câu buộc người làm slide quyết định trước mình muốn chứng minh điều gì. Nhãn như Tổng quan cho phép trình bày mà chưa có quan điểm.","Trí nhớ làm việc của người nghe có hạn, nên 12 con số cạnh tranh nhau và gần như không con số nào được nhớ. Ít con số hơn thì mỗi con nổi hơn.","Bộ tiêu đề đọc nối thành chuyện còn cho sếp đọc lướt: chỉ đọc tiêu đề đã nắm ý chính, rồi dừng ở slide nào muốn xem số chi tiết."],
  counter:"Giả sử sếp của Tuấn cần một tờ tổng hợp để in ra đọc lúc di chuyển, không có người trình bày. Một ý một slide có thể làm tờ in rời rạc và phải lật qua lại. Dấu hiệu nhận ra: tài liệu được đọc một mình và cần nhiều thông tin trên một trang. Khi đó vẫn giữ tiêu đề kết luận nhưng cho phép nhiều bằng chứng hơn, kèm chú thích rõ.",
  deeper:"Người làm nghề phân biệt slide để trình bày với tài liệu để đọc: loại đầu cần ít chữ và một ý, loại sau cần đủ để đứng một mình. Đánh đổi là tách nhiều slide làm bộ dài ra, nhưng mỗi slide dễ nhớ hơn. Tín hiệu nên theo là câu hỏi lặp lại của sếp sau buổi họp: nếu họ vẫn hỏi quý này tăng hay giảm, tiêu đề chưa nói được kết luận. Khái niệm kề cận là kết luận trước, số sau. Phép kiểm tra trong tuần: đọc liền ba tiêu đề slide cho một người không dự họp và xem họ kể lại được chuyện gì.",
  apply:'Mở bộ slide gần nhất của bạn, viết lại tiêu đề 3 slide thành câu có kết luận. Đọc liền 3 câu xem có thành câu chuyện không.',
  mistakes:['Tiêu đề slide là nhãn chủ đề như "Tổng quan", "Kết quả".','Nhồi mọi biểu đồ vào một slide vì sợ sếp nghĩ mình làm ít.'],
  q:[
  { type:'mcq', stem:'Tiêu đề slide nào giúp người xem hiểu ngay ý chính?',
    options:[{k:'a',t:'Kết quả kinh doanh quý 3'},{k:'b',t:'Tổng quan các chỉ số chính của quý 3 trên sàn'},
             {k:'c',t:'Doanh thu quý 3 tăng 18% nhờ đơn tăng'},{k:'d',t:'Phân tích doanh thu (xem biểu đồ bên dưới)'}],
    answer:'c', why:{a:'Nhãn chủ đề, không cho biết kết quả tốt hay xấu.',
      b:'Dài hơn nhưng vẫn chỉ là nhãn; người xem phải tự đọc biểu đồ.',
      c:'Đúng. Tiêu đề là một câu có kết luận và lý do.',
      d:'Đẩy việc rút kết luận sang người xem.'} },
  { type:'mcq', stem:'Slide của bạn có 4 biểu đồ, và bạn muốn sếp nhớ đúng một điều: chi phí quảng cáo tăng nhanh hơn doanh thu. Bạn sửa gì?',
    options:[{k:'a',t:'Giữ cả 4 biểu đồ nhưng tô đỏ biểu đồ chi phí để nổi bật hơn'},{k:'b',t:'Thêm một đoạn văn giải thích dưới 4 biểu đồ'},
             {k:'c',t:'Giữ 4 biểu đồ, thu nhỏ để có chỗ thêm bảng số chi tiết'},{k:'d',t:'Một slide: tiêu đề nói ý đó, chỉ giữ chi phí và doanh thu'}],
    answer:'d', why:{a:'Tô màu giúp một chút nhưng 3 biểu đồ còn lại vẫn kéo mắt đi chỗ khác.',
      b:'Thêm chữ làm slide nặng hơn; người xem đọc chữ và nghe bạn cùng lúc sẽ không nhớ gì.',
      c:'Nhỏ hơn và nhiều hơn là ngược hướng.',
      d:'Đúng. Tiêu đề nói kết luận, hai con số chứng minh, phần còn lại sang phụ lục.'} },
  { type:'calc', stem:'Chi phí quảng cáo quý 2 là 200 triệu, quý 3 là 270 triệu. Chi phí tăng bao nhiêu phần trăm?',
    unit:'%', ans:35, tol:0.5, wrong:[[70,'NHAM_SO_TUYET_DOI'],[25.9,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Mức tăng = 270 − 200 = 70 triệu.','Tỉ lệ tăng = 70 ÷ 200 (số gốc là quý 2) = <b>35%</b>.'] },
  { type:'mcq', stem:'Cách kiểm tra nhanh một bộ slide có mạch lạc hay không là gì?',
    options:[{k:'a',t:'Đọc liền các tiêu đề slide xem có thành câu chuyện đủ nghĩa'},{k:'b',t:'Đếm số biểu đồ, càng nhiều biểu đồ thì càng thể hiện phân tích sâu và kỹ'},
             {k:'c',t:'Kiểm tra font chữ và màu sắc có đồng bộ không'},{k:'d',t:'Xem bộ slide có đủ 20 trang trở lên không'}],
    answer:'a', why:{a:'Đúng. Nếu tiêu đề là câu kết luận, đọc liền chúng chính là bản tóm tắt.',
      b:'Nhiều biểu đồ không có nghĩa là rõ ý; thường là ngược lại.',
      c:'Đồng bộ hình thức tốt nhưng không nói gì về mạch ý.',
      d:'Độ dài không đo được sự mạch lạc.'} },
  { type:'mcq', stem:'Chỉ số đánh giá sao ổn định ở 4,8 suốt quý. Nên xử lý thế nào trong báo cáo?',
    options:[{k:'a',t:'Làm hẳn một slide riêng cho chỉ số đánh giá để khoe thành tích'},{k:'b',t:'Chuyển xuống phụ lục hoặc một dòng, vì nó không đổi và không cần quyết gì'},
             {k:'c',t:'Bỏ hẳn, không ghi ở đâu cả để tiết kiệm chỗ'},{k:'d',t:'Đặt lên slide đầu tiên vì đó là con số đẹp nhất'}],
    answer:'b', why:{a:'Một slide riêng cho con số không đổi làm loãng các ý cần quyết.',
      b:'Đúng. Ghi nhận ngắn gọn, dành chỗ chính cho thứ thay đổi hoặc cần hành động.',
      c:'Vẫn nên có để sếp biết nó ổn; chỉ không cần chiếm chỗ chính.',
      d:'Đẹp nhưng không phải ý chính của quý; mở đầu bằng nó làm lệch trọng tâm.'} },
  { type:'mcq', stem:'Tình huống mới: đồng nghiệp muốn dồn 3 kết luận vào một slide "để sếp thấy hết". Bạn góp ý gì?',
    options:[{k:'a',t:'Đồng ý, vì ít slide thì buổi họp sẽ ngắn và gọn hơn'},{k:'b',t:'Đồng ý nhưng đổi sang cỡ chữ nhỏ hơn cho vừa'},
             {k:'c',t:'Chuyển cả 3 kết luận sang email gửi trước buổi họp, slide chỉ để biểu đồ minh hoạ'},{k:'d',t:'Tách thành 3 slide, mỗi slide một kết luận có bằng chứng'}],
    answer:'d', why:{a:'Số slide ít không làm họp ngắn hơn nếu mỗi slide phải giải thích lâu.',
      b:'Chữ nhỏ làm khó đọc hơn, không giải quyết được việc quá nhiều ý.',
      c:'Gửi trước thì tốt, nhưng slide không có kết luận thì trong họp lại phải đoán ý.',
      d:'Đúng. Ba ý, ba slide; thời gian mỗi slide ngắn và ý nào cũng được nhớ.'} },
  { type:'mcq', stem:'Vì sao sếp của Tuấn hỏi lại "Quý này tăng hay giảm?" dù slide có đủ số?',
    options:[{k:'a',t:'Vì sếp không đọc kỹ báo cáo trước khi vào họp'},{k:'b',t:'Vì 12 con số ngang nhau, không số nào được nói là ý chính'},
             {k:'c',t:'Vì biểu đồ dùng sai màu, khó phân biệt các đường'},{k:'d',t:'Vì doanh thu quý 3 thực ra không tăng mà chỉ đi ngang'}],
    answer:'b', why:{a:'Đổ lỗi cho người nghe không sửa được cách trình bày.',
      b:'Đúng. Khi mọi con số cùng in đậm, không con số nào nổi lên; người xem không biết đâu là kết luận.',
      c:'Màu có thể góp phần nhưng không phải lý do chính.',
      d:'Doanh thu có tăng 18%; vấn đề là slide không nói điều đó.'} },
  ]},

/* ------------------------------------------------------------------ 03 */
{ id:'B:dl09-03', skill:'measure', read:'7 phút', t:'"Doanh thu 850 triệu" — cao hay thấp?',
  situation:'Hương báo cáo: "Tháng 10 cửa hàng online bán được 850 triệu." Sếp hỏi: "Thế là tốt hay không?". Hương lúng túng. Số liệu cô có: kế hoạch tháng 10 là 800 triệu, tháng 10 năm ngoái đạt 900 triệu, tháng 9 vừa rồi đạt 700 triệu. Một đối thủ cùng phân khúc báo tăng trưởng 20% so với cùng kỳ.',
  concept:{ name:'Một con số đứng một mình không nói gì',
    body:'Con số chỉ có nghĩa khi đặt cạnh một <b>mốc so sánh</b>. Ba mốc hay dùng: <b>kế hoạch</b> (có làm đúng cam kết không), <b>cùng kỳ năm trước</b> (loại bỏ yếu tố mùa vụ), <b>kỳ trước</b> (xu hướng ngắn hạn, nhưng dễ lẫn mùa vụ). Thêm mốc thứ tư khi có: <b>thị trường hoặc đối thủ</b>. Chọn mốc phù hợp với câu hỏi, và nói rõ đang so với mốc nào; đừng chỉ chọn mốc làm mình đẹp.' },
  example:'850 triệu so với kế hoạch 800: đạt 106%. So với tháng 9 (700): tăng 21%, nhưng tháng 10 thường có mùa mua sắm nên tăng là bình thường. So với cùng kỳ (900): giảm khoảng 6%, trong khi đối thủ tăng 20%. Câu trả lời trung thực: "Vượt kế hoạch 6%, nhưng thấp hơn cùng kỳ 6% trong lúc thị trường tăng — kế hoạch năm nay có lẽ đặt thấp."',
  takeaway:'Luôn nói "so với cái gì"; chọn mốc theo câu hỏi, không theo mốc làm mình đẹp.',
  points:["Mỗi mốc trả lời một câu hỏi riêng: kế hoạch hỏi có giữ cam kết không, cùng kỳ hỏi có tốt lên không, kỳ trước hỏi đà có đổi không.","Khi các mốc cho kết luận trái chiều, đó là thông tin chứ không phải rắc rối. Vượt kế hoạch mà thấp hơn cùng kỳ thường chỉ ra kế hoạch đặt quá thấp.","Mốc đối thủ giúp phân biệt vấn đề của riêng mình với xu hướng thị trường. Nếu cả ngành tăng mà mình đi xuống, thì lý do nằm ở mình."],
  counter:"Giả sử đối thủ cùng phân khúc vừa mở sang kênh mới và chạy một đợt khuyến mãi rất mạnh trong kỳ. Mức tăng 20% của họ khi đó không phản ánh thị trường, và Hương sẽ lo quá mức nếu lấy làm mốc. Dấu hiệu nhận ra: đối thủ đổi mô hình hoặc kênh trong kỳ. Hãy so với vài đối thủ hoặc dữ liệu ngành rộng hơn trước khi kết luận.",
  deeper:"Người làm nghề chọn mốc trước khi nhìn số để khỏi bị cám dỗ chọn mốc cho đẹp. Đánh đổi là kế hoạch dễ bị đặt thấp để về sau vượt, nên mốc kế hoạch cần được xem lại, còn mốc cùng kỳ cần xem kỳ gốc có bình thường không. Tín hiệu nên theo là khoảng cách giữa tốc độ tăng của mình và của thị trường qua nhiều tháng, không chỉ một tháng. Khái niệm kề cận là thị phần. Phép kiểm tra trong tuần: lấy một con số bạn vừa báo, đặt cạnh kế hoạch, kỳ trước và cùng kỳ, rồi viết một câu nêu rõ mốc.",
  apply:'Lấy một con số bạn báo cáo gần đây, đặt nó cạnh ba mốc: kế hoạch, kỳ trước, cùng kỳ. Viết một câu kết luận có nêu rõ mốc.',
  mistakes:['Chỉ so với tháng trước khi có yếu tố mùa vụ.','Chọn mốc so sánh làm kết quả trông đẹp nhất và bỏ qua các mốc khác.'],
  q:[
  { type:'mcq', stem:'Doanh thu tháng 10 là 850 triệu. Thông tin nào cần thêm nhất để biết con số này tốt hay xấu?',
    options:[{k:'a',t:'Số lượng sản phẩm đang bán trên cửa hàng'},{k:'b',t:'Số nhân viên trong đội marketing và ngân sách mà đội được cấp cho cả năm'},
             {k:'c',t:'Kế hoạch tháng 10 và cùng kỳ năm ngoái'},{k:'d',t:'Doanh thu trung bình của mỗi ngày trong tháng'}],
    answer:'c', why:{a:'Số sản phẩm không cho biết doanh thu đạt hay hụt.',
      b:'Quy mô đội và ngân sách là bối cảnh, không phải mốc so sánh cho doanh thu.',
      c:'Đúng. Có mốc so sánh mới đánh giá được con số.',
      d:'Chia theo ngày chỉ là cùng con số dưới dạng khác.'} },
  { type:'mcq', stem:'Bạn đạt 106% kế hoạch nhưng thấp hơn cùng kỳ 6%, trong khi đối thủ tăng 20%. Bạn chọn nói thế nào với sếp?',
    options:[{k:'a',t:'Chỉ nói vượt kế hoạch 6%, vì đó là cam kết đã được sếp duyệt từ đầu năm'},{k:'b',t:'Nói vượt kế hoạch, nhưng giảm so với cùng kỳ khi thị trường tăng'},
             {k:'c',t:'Chỉ nói so với tháng 9 tăng 21% vì con số ấn tượng nhất'},{k:'d',t:'Nói cả ba mốc nhưng không kết luận, để sếp tự đánh giá'}],
    answer:'b', why:{a:'Đúng cam kết nhưng che mất tín hiệu quan trọng: mình đang mất thị phần.',
      b:'Đúng. Nêu cả hai mốc và điều chúng cho thấy; sếp cần biết kế hoạch có thể đặt thấp.',
      c:'Tháng 10 luôn cao hơn tháng 9 vì mùa vụ; chọn mốc này là tô đẹp.',
      d:'Đưa đủ mốc là tốt, nhưng vẫn phải có kết luận.'} },
  { type:'calc', stem:'Doanh thu tháng 10 năm nay 850 triệu, tháng 10 năm ngoái 900 triệu. Doanh thu thay đổi bao nhiêu phần trăm so với cùng kỳ? (giảm ghi số âm, làm tròn 1 chữ số thập phân)',
    unit:'%', ans:-5.6, tol:0.1, wrong:[[-5.9,'SAI_MAU_SO'],[-50,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO'],
    steps:['Chênh lệch = 850 − 900 = −50 triệu.','Chia cho số gốc (năm ngoái): −50 ÷ 900 ≈ <b>−5,6%</b>.'] },
  { type:'mcq', stem:'Vì sao so với cùng kỳ năm trước thường đáng tin hơn so với tháng trước khi bán hàng tiêu dùng?',
    options:[{k:'a',t:'Vì số liệu năm trước đã được kiểm toán nên chính xác hơn'},{k:'b',t:'Vì tháng trước thường có ít ngày bán hơn tháng này'},
             {k:'c',t:'Vì sếp thường chỉ nhớ số liệu của năm trước'},{k:'d',t:'Vì cùng mùa vụ, loại được ảnh hưởng của lễ, Tết, sale'}],
    answer:'d', why:{a:'Độ chính xác không phải lý do chính; lý do là cùng điều kiện mùa vụ.',
      b:'Chênh số ngày chỉ là phần nhỏ; lý do chính là cùng kỳ có cùng mùa vụ, lễ Tết.',
      c:'Không liên quan đến trí nhớ của sếp.',
      d:'Đúng. Tháng 10 so với tháng 10 thì cùng nhịp mua sắm.'} },
  { type:'mcq', stem:'Tình huống mới: một cửa hàng mới mở được 4 tháng, chưa có cùng kỳ năm trước. Mốc so sánh nào hợp lý?',
    options:[{k:'a',t:'Kế hoạch đã đặt và kết quả của các cửa hàng cũ lúc mới mở'},{k:'b',t:'Không so gì, vì cửa hàng mới thì chưa có dữ liệu để so sánh'},
             {k:'c',t:'So với cửa hàng lớn nhất chuỗi ở thời điểm hiện tại'},{k:'d',t:'So với doanh thu trung bình toàn ngành bán lẻ cả nước năm nay'}],
    answer:'a', why:{a:'Đúng. Kế hoạch và "cùng tuổi" của cửa hàng khác là mốc công bằng.',
      b:'Luôn tìm được mốc; báo số trơ trọi thì sếp không đánh giá được.',
      c:'Cửa hàng lâu năm đã có khách quen; so thế là không công bằng.',
      d:'Trung bình toàn ngành quá rộng, khác quy mô và phân khúc.'} },
  { type:'mcq', stem:'Đồng nghiệp chỉ báo "tăng 21% so với tháng trước" cho tháng 11 có ngày sale 11.11. Rủi ro là gì?',
    options:[{k:'a',t:'Con số 21% bị tính sai vì dùng nhầm mẫu số'},{k:'b',t:'Sếp tưởng đội làm tốt, trong khi mức tăng có thể chỉ do mùa sale'},
             {k:'c',t:'Báo cáo sẽ quá ngắn, sếp nghĩ đội lười phân tích và thiếu số liệu'},{k:'d',t:'Tháng trước có ít ngày hơn nên con số tăng trưởng bị méo đi nhiều'}],
    answer:'b', why:{a:'Phép tính có thể đúng; vấn đề ở mốc được chọn.',
      b:'Đúng. Sale 11.11 năm nào cũng có; cần so cùng kỳ để biết đội thực sự làm tốt hơn không.',
      c:'Độ dài không phải vấn đề; vấn đề là kết luận sai.',
      d:'Tháng 10 và 11 chỉ lệch một ngày, không đủ giải thích 21%.'} },
  { type:'mcq', stem:'Khi nào nên thêm mốc "đối thủ hoặc thị trường" vào báo cáo?',
    options:[{k:'a',t:'Chỉ khi mình tăng trưởng tốt hơn đối thủ, để khoe'},{k:'b',t:'Hằng tháng, kể cả khi số liệu đối thủ chỉ là ước đoán'},
             {k:'c',t:'Khi có nguồn đáng tin và câu hỏi là mình mạnh lên hay yếu đi'},{k:'d',t:'Chỉ khi có số doanh thu chính xác đến từng đơn của đối thủ'}],
    answer:'c', why:{a:'Chỉ đưa khi đẹp là chọn mốc thiên lệch.',
      b:'Số đoán mò làm yếu cả báo cáo.',
      c:'Đúng. Mốc thị trường trả lời câu hỏi thị phần, miễn là có nguồn đáng tin.',
      d:'Không cần chính xác tới từng đơn; nguồn công khai hoặc dữ liệu sàn đủ dùng nếu nêu rõ mức độ chắc.'} },
  ]},

/* ------------------------------------------------------------------ 04 */
{ id:'B:dl09-04', skill:'comm', read:'6 phút', t:'"CAC 187.432 đồng" hay "khoảng 190 nghìn"?',
  situation:'Minh báo cáo cho ban giám đốc một chuỗi phòng tập: "Chi phí có một hội viên mới quý này là 187.432 đồng, tỉ lệ gia hạn 63,47%, doanh thu trung bình mỗi hội viên 2.841.560 đồng." Cuối buổi, không ai nhắc lại được con số nào. Một giám đốc hỏi: "Chi phí có khách mới là bao nhiêu nhỉ, hai trăm hay ba trăm nghìn?".',
  concept:{ name:'Làm tròn để người nghe nhớ',
    body:'Khi nói, người nghe chỉ giữ được 2–3 chữ số có nghĩa. Làm tròn tới mức vẫn đủ để quyết định: 187.432 đồng thành <b>khoảng 190 nghìn</b>, 63,47% thành <b>khoảng 63%</b>, 2.841.560 thành <b>2,8 triệu</b>. Số chính xác vẫn để trong file đính kèm. Hai điều cần giữ: làm tròn nhất quán (cùng đơn vị, cùng mức), và không làm tròn khi chênh lệch nhỏ chính là điều cần nói (ví dụ 49,6% và 50,4%) hoặc khi số thật nằm sát ngưỡng quyết định.' },
  example:'Minh nói lại: "Có một hội viên mới tốn khoảng 190 nghìn, mỗi hội viên mang về 2,8 triệu, hơn 60% gia hạn." Ba con số dễ nhớ, và ban giám đốc tự nhẩm được: doanh thu mỗi hội viên gấp khoảng 15 lần chi phí có hội viên đó. Lưu ý: đó là doanh thu, chưa phải lãi; muốn biết có khách có đáng hay không phải so chi phí có khách với <b>lãi</b> mỗi hội viên sau chi phí phục vụ, không so với doanh thu. Khi được hỏi chi tiết, Minh mở bảng số chính xác. Làm tròn không làm mất thông tin cần để quyết định.',
  takeaway:'Nói số tròn đủ để quyết định; số chính xác để trong file, đưa ra khi được hỏi.',
  apply:'Chọn 3 con số trong báo cáo gần nhất, làm tròn từng số về 2 chữ số có nghĩa rồi đọc to thành một câu.',
  mistakes:['Đọc nguyên số lẻ tới hàng đơn vị vì nghĩ như vậy mới chính xác.','Làm tròn mỗi số một kiểu (triệu, nghìn, đồng lẫn lộn).'],
  q:[
  { type:'mcq', stem:'Khi trình bày bằng lời trong cuộc họp, cách nói nào giúp người nghe nhớ tốt nhất?',
    options:[{k:'a',t:'"Chi phí có khách là 187.432 đồng"'},{k:'b',t:'"Chi phí có khách là một trăm tám mươi bảy nghìn bốn trăm ba mươi hai đồng"'},
             {k:'c',t:'"Chi phí có khách vào khoảng 190 nghìn"'},{k:'d',t:'"Chi phí có khách ở mức trung bình khá"'}],
    answer:'c', why:{a:'Đủ chính xác nhưng quá nhiều chữ số để giữ trong đầu khi nghe.',
      b:'Đọc thành chữ còn dài hơn và khó nhớ hơn.',
      c:'Đúng. Hai chữ số có nghĩa, đủ để so sánh và quyết định.',
      d:'Bỏ hẳn con số thì người nghe không so được với gì.'} },
  { type:'mcq', stem:'Tỉ lệ bình chọn hai mẫu bao bì là 49,6% và 50,4%. Bạn làm tròn và trình bày thế nào?',
    options:[{k:'a',t:'Giữ số lẻ và nói rõ hai mẫu gần như ngang nhau'},{k:'b',t:'Làm tròn thành 50% và 50% cho gọn và dễ nhớ'},
             {k:'c',t:'Làm tròn thành 49% và 51% để thấy rõ có một mẫu thắng'},{k:'d',t:'Chỉ nói mẫu B thắng, không cần nêu con số nào để tránh rối'}],
    answer:'a', why:{a:'Đúng. Khi chênh lệch nhỏ là thông tin chính, giữ số lẻ và nói thẳng ý nghĩa của nó.',
      b:'Làm tròn thành 50/50 thì người nghe không biết đã có số lẻ nào.',
      c:'Làm tròn sai hướng để tạo ra người thắng là bóp méo số liệu.',
      d:'Nói "thắng" với 0,8 điểm chênh là phóng đại.'} },
  { type:'calc', stem:'Chi phí có một hội viên mới là 190 nghìn, mỗi hội viên mang về doanh thu 2,8 triệu. Doanh thu gấp chi phí bao nhiêu lần? (làm tròn 1 chữ số thập phân)',
    unit:'lần', ans:14.7, tol:0.1, wrong:[[1.5,'SAI_TINH_TOAN'],[0.07,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Đổi cùng đơn vị: 2,8 triệu = 2.800 nghìn.','2.800 ÷ 190 ≈ <b>14,7 lần</b>. (Đây là doanh thu chia chi phí có khách, chưa phải lãi chia chi phí có khách.)'] },
  { type:'mcq', stem:'Một slide ghi: "Doanh thu 2,8 triệu; chi phí có khách 190.000đ; lãi gộp (biên 40%) 1.120 nghìn". Lỗi chính là gì?',
    options:[{k:'a',t:'Làm tròn quá nhiều nên mất độ chính xác của số liệu'},{k:'b',t:'Thiếu biểu đồ minh hoạ cho các con số'},
             {k:'c',t:'Con số lãi tính sai, lẽ ra phải là một con số khác hẳn'},{k:'d',t:'Ba con số dùng ba kiểu đơn vị, người đọc phải tự quy đổi'}],
    answer:'d', why:{a:'Mức làm tròn chấp nhận được; vấn đề là đơn vị không nhất quán.',
      b:'Biểu đồ không cần thiết cho ba con số.',
      c:'2.800 × 40% = 1.120 nghìn, phép tính đúng.',
      d:'Đúng. Triệu, đồng, nghìn lẫn lộn khiến so sánh mất công. Nên đưa hết về cùng một đơn vị.'} },
  { type:'mcq', stem:'Tình huống mới: kế toán phàn nàn slide ghi "doanh thu khoảng 3,2 tỉ" trong khi sổ là 3.176 triệu. Bạn phản hồi thế nào?',
    options:[{k:'a',t:'Đổi slide sang số 3.176.482.000đ để khỏi bị ai phàn nàn nữa'},{k:'b',t:'Giữ số tròn trên slide, ghi chú "số chính xác ở phụ lục"'},
             {k:'c',t:'Bỏ hẳn con số doanh thu khỏi slide cho an toàn'},{k:'d',t:'Giải thích rằng làm tròn là chuẩn nên kế toán không cần quan tâm'}],
    answer:'b', why:{a:'Số đầy đủ làm slide khó đọc; người nghe không nhớ nổi.',
      b:'Đúng. Số tròn cho người nghe, số chính xác cho người kiểm tra; cả hai đều có chỗ.',
      c:'Bỏ số thì mất bằng chứng cho kết luận.',
      d:'Gạt đi lo ngại của kế toán làm mất đồng minh; chỉ cần chỉ chỗ có số gốc.'} },
  { type:'mcq', stem:'Quy tắc nội bộ: chương trình gia hạn đạt khi tỉ lệ gia hạn từ 63% trở lên. Số thật là 63,47%. Bạn nói thế nào trong họp?',
    options:[{k:'a',t:'"Hơn 63% hội viên gia hạn", giữ đủ chữ số để thấy đã vượt ngưỡng'},{k:'b',t:'"Khoảng 60% hội viên gia hạn", vì làm tròn tới hàng chục là dễ nhớ nhất'},
             {k:'c',t:'"Gần 2/3 hội viên gia hạn", vì phân số dễ hình dung và nghe thuyết phục'},{k:'d',t:'"63,47% hội viên gia hạn", vì quyết định thì cần giữ các chữ số thập phân'}],
    answer:'a', why:{a:'Đúng. Ngưỡng 63% nằm sát số thật, nên phải giữ tới chữ số đó; làm tròn xong người nghe vẫn kiểm tra được đạt hay chưa.',
      b:'Làm tròn xuống 60% khiến chương trình trông như chưa đạt ngưỡng 63%; quyết định bị đảo vì mức làm tròn quá thô.',
      c:'2/3 là 66,7%, cao hơn số thật; nó thổi nhẹ kết quả và vẫn không cho thấy mình vượt ngưỡng bao nhiêu.',
      d:'Hai chữ số thập phân là thừa: thấy được hơn 63% đã đủ để quyết định, phần lẻ để trong file.'} },
  { type:'mcq', stem:'Quy tắc duyệt ngân sách: chi phí có một hội viên mới phải dưới 190 nghìn. Số thật là 187.432 đồng. Làm tròn thành "khoảng 200 nghìn" có vấn đề gì?',
    options:[{k:'a',t:'Không có vấn đề, vì làm tròn càng mạnh thì người nghe càng dễ nhớ'},{k:'b',t:'Bị sai quy tắc làm tròn toán học lên hàng trăm nghìn'},
             {k:'c',t:'Lệch khoảng 7% và đẩy con số vượt ngưỡng 190 nghìn, quyết định bị đảo'},{k:'d',t:'Chỉ có vấn đề nếu sếp là người làm tài chính'}],
    answer:'c', why:{a:'Làm tròn quá tay có thể đẩy con số qua ngưỡng quyết định.',
      b:'Về toán thì đúng khi làm tròn tới hàng trăm nghìn; vấn đề là mức làm tròn quá thô.',
      c:'Đúng. 200 nghìn nằm trên ngưỡng còn 187 nghìn nằm dưới; phải làm tròn tới mức vẫn đủ để quyết định (190 hoặc tốt hơn là 187 nghìn).',
      d:'Sai lệch ảnh hưởng quyết định bất kể người nghe là ai.'} },
  ]},

/* ------------------------------------------------------------------ 05 */
{ id:'B:dl09-05', skill:'measure', read:'7 phút', t:'"Tăng 200%" hay "tăng 30 đơn"?',
  situation:'Một thương hiệu mỹ phẩm thuần chay chạy thử kênh Zalo. Báo cáo tuần ghi: "Đơn từ Zalo tăng 200%!". Sếp hào hứng định dồn thêm ngân sách. Nhìn kỹ: tuần trước Zalo có 15 đơn, tuần này 45 đơn. Cùng tuần, kênh Shopee tăng từ 1.200 lên 1.320 đơn, tức tăng 10%, và không ai nhắc tới.',
  concept:{ name:'Phần trăm và số tuyệt đối đi cùng nhau',
    body:'Phần trăm cho biết <b>tốc độ</b>, số tuyệt đối cho biết <b>quy mô</b>. Trên nền nhỏ, phần trăm phóng đại: từ 15 lên 45 là tăng 200% nhưng chỉ thêm 30 đơn. Trên nền lớn, phần trăm nhỏ lại che mất khối lượng: 10% của 1.200 là 120 đơn, gấp 4 lần Zalo. Khi báo cáo, nói cả hai: "tăng 200%, tức thêm 30 đơn". Với tỉ lệ (CTR, tỉ lệ chuyển đổi), còn phải phân biệt <b>điểm phần trăm</b> với <b>phần trăm</b>.' },
  example:'Viết lại: "Shopee thêm 120 đơn (tăng 10%), vẫn là nguồn tăng chính. Zalo thêm 30 đơn (gấp 3 lần tuần trước) — tín hiệu đáng thử tiếp, nhưng nền còn nhỏ." Sếp thấy ngay: tăng ngân sách Zalo là thử nghiệm nhỏ, không phải chuyển trọng tâm. Tương tự, tỉ lệ chuyển đổi từ 2% lên 3% là tăng 1 điểm phần trăm, hay tăng 50%; nói rõ là cái nào.',
  takeaway:'Phần trăm đi kèm số tuyệt đối: một cái nói tốc độ, một cái nói quy mô.',
  points:["Phần trăm tính trên nền nhỏ dễ dao động mạnh vì thêm vài đơn đã đổi cả con số. Nền càng nhỏ thì mức tăng 200% càng ít báo hiệu một xu hướng bền.","Số đơn thực cho phép so các kênh trên cùng một thước, còn phần trăm so mỗi kênh với chính nó. Muốn chia ngân sách, bạn cần thước chung.","Viết thành một câu có cả hai giúp sếp quyết định đúng cỡ: thử nghiệm nhỏ hay chuyển trọng tâm. Chỉ một con số thì cỡ quyết định dễ bị đoán sai."],
  counter:"Giả sử mỗi đơn Zalo đến từ một khách mua cho cả nhóm bạn, rồi nhóm đó giới thiệu thêm. Chỉ nhìn 30 đơn tăng thêm sẽ đánh giá thấp kênh, và số đơn thực cũng có thể che mất tiềm năng. Dấu hiệu nhận ra: giá trị đơn cao hơn hoặc khách quay lại nhiều hơn ở kênh nhỏ. Khi đó nhìn thêm chất lượng khách, không chỉ số đơn.",
  deeper:"Người làm nghề nhìn mức tăng như hai câu hỏi tách nhau: kênh này nhanh hay chậm, và nó lớn hay nhỏ. Kênh nhỏ tăng nhanh cần thử thêm, kênh lớn tăng chậm cần bảo vệ, và hai việc cần ngân sách khác nhau. Tín hiệu nên theo là mức tăng có giữ được qua vài tuần liền không, vì một tuần nhảy vọt thường chưa nói gì. Khái niệm kề cận là hiệu ứng nền thấp. Phép kiểm tra trong tuần: lấy báo cáo gần nhất, viết lại từng mức tăng thành câu có cả phần trăm lẫn số đơn thêm, rồi xếp kênh theo số đơn thêm.",
  apply:'Tìm một mức tăng bằng phần trăm trong báo cáo gần nhất và viết lại thành một câu có cả phần trăm lẫn số tuyệt đối.',
  mistakes:['Khoe phần trăm lớn trên nền rất nhỏ.','Nói "tăng 1%" khi thực ra là tăng 1 điểm phần trăm.'],
  q:[
  { type:'mcq', stem:'Kênh A tăng 200%, kênh B tăng 10%. Kênh nào đóng góp nhiều đơn tăng thêm hơn?',
    options:[{k:'a',t:'Kênh A, vì 200% lớn gấp 20 lần 10%'},{k:'b',t:'Kênh B, vì kênh tăng chậm thường là kênh to'},
             {k:'c',t:'Chưa biết được, cần số đơn gốc của mỗi kênh'},{k:'d',t:'Hai kênh bằng nhau vì cùng tăng trưởng dương'}],
    answer:'c', why:{a:'Phần trăm không cho biết quy mô; 200% của 15 chỉ là 30.',
      b:'Tăng chậm không cho biết kênh to hay nhỏ; phải có số đơn gốc mới tính được.',
      c:'Đúng. Cần nền gốc để quy ra số tuyệt đối.',
      d:'Cùng dương không có nghĩa bằng nhau.'} },
  { type:'mcq', stem:'Sếp muốn dồn ngân sách vào Zalo vì "tăng 200%". Bạn nên làm gì?',
    options:[{k:'a',t:'Đồng ý ngay vì tăng trưởng nhanh là tín hiệu tốt nhất để đầu tư'},{k:'b',t:'Phản đối vì Zalo quá nhỏ, không đáng để đầu tư'},
             {k:'c',t:'Im lặng, để sếp tự quyết định theo cảm nhận'},{k:'d',t:'Nói rõ 200% là thêm 30 đơn, đề xuất tăng nhỏ để thử'}],
    answer:'d', why:{a:'Nền nhỏ khiến 200% dễ là dao động; dồn tiền theo đó là rủi ro.',
      b:'Tín hiệu vẫn đáng thử; phản đối hẳn là bỏ lỡ cơ hội.',
      c:'Người có số liệu phải nói ra con số đầy đủ.',
      d:'Đúng. Đặt phần trăm cạnh số tuyệt đối, đề xuất bước thử tương xứng.'} },
  { type:'calc', stem:'Tỉ lệ chuyển đổi tăng từ 2% lên 3%. Theo cách tính tương đối, tỉ lệ này tăng bao nhiêu phần trăm?',
    unit:'%', ans:50, tol:0.5, wrong:[[1,'NHAM_DIEM_PHAN_TRAM'],[33.3,'SAI_MAU_SO']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Chênh lệch = 3% − 2% = 1 điểm phần trăm.','Tăng tương đối = 1 ÷ 2 = <b>50%</b>.'] },
  { type:'mcq', stem:'Câu nào mô tả đúng việc CTR đi từ 1,5% lên 2%?',
    options:[{k:'a',t:'CTR tăng 0,5 điểm phần trăm, tức tăng khoảng 33%'},{k:'b',t:'CTR tăng 0,5%, một mức tăng rất nhỏ không đáng kể'},
             {k:'c',t:'CTR tăng 2%, đạt mục tiêu đề ra'},{k:'d',t:'CTR tăng 25% vì 0,5 chia cho 2 bằng 0,25'}],
    answer:'a', why:{a:'Đúng. 0,5 điểm phần trăm; tương đối là 0,5 ÷ 1,5 ≈ 33%.',
      b:'Nhầm điểm phần trăm với phần trăm; mức tăng tương đối là 33%, không nhỏ.',
      c:'2% là mức mới, không phải mức tăng.',
      d:'Chia sai mẫu số; phải chia cho mức gốc 1,5.'} },
  { type:'mcq', stem:'Tình huống mới: sản phẩm mới bán tuần đầu 5 hộp, tuần hai 20 hộp. Đội muốn báo "tăng 300%". Bạn sửa câu thế nào?',
    options:[{k:'a',t:'Giữ "tăng 300%" vì phép tính đã đúng và dễ nhớ'},{k:'b',t:'"Tuần hai bán 20 hộp, gấp 4 tuần đầu; nền còn nhỏ"'},
             {k:'c',t:'"Doanh số bùng nổ tuần thứ hai"'},{k:'d',t:'Không báo gì cho tới khi có đủ một tháng số liệu'}],
    answer:'b', why:{a:'Đúng toán học nhưng tạo ấn tượng sai về quy mô.',
      b:'Đúng. Số tuyệt đối, bội số dễ hiểu, và cảnh báo nền nhỏ.',
      c:'Tính từ cảm xúc không có số, còn phóng đại.',
      d:'Tín hiệu sớm vẫn có ích nếu nói đúng quy mô.'} },
  { type:'mcq', stem:'Khi nào số tuyệt đối quan trọng hơn phần trăm trong báo cáo cho sếp?',
    options:[{k:'a',t:'Khi so tốc độ tăng giữa các kênh khác quy mô'},{k:'b',t:'Khi số đơn, số tiền trông lớn và ấn tượng hơn'},
             {k:'c',t:'Khi báo cáo chỉ có một kênh để theo dõi'},{k:'d',t:'Khi quyết định về tiền, người, hàng tồn cần quy mô'}],
    answer:'d', why:{a:'So tốc độ giữa các kênh khác quy mô là lúc phần trăm hữu ích; số tuyệt đối cần khi quyết định cần quy mô.',
      b:'Chọn theo cái nào đẹp là thiên lệch.',
      c:'Số kênh không quyết định; mục đích quyết định mới quyết định.',
      d:'Đúng. Nhập hàng, tuyển người, chia ngân sách đều cần con số tuyệt đối.'} },
  { type:'mcq', stem:'Shopee tăng từ 1.200 lên 1.320 đơn. Vì sao con số này dễ bị bỏ qua trong báo cáo?',
    options:[{k:'a',t:'Vì Shopee là kênh cũ nên sếp không còn quan tâm'},{k:'b',t:'Vì 10% nghe nhỏ, dù thêm 120 đơn, gấp 4 lần Zalo'},
             {k:'c',t:'Vì số liệu Shopee thường không chính xác'},{k:'d',t:'Vì 120 đơn tăng thêm thực ra là do mùa vụ mà thôi'}],
    answer:'b', why:{a:'Kênh cũ vẫn là nguồn doanh thu chính; lý do là cách trình bày.',
      b:'Đúng. Phần trăm nhỏ trên nền lớn che mất khối lượng thực.',
      c:'Không có dữ kiện nào nói số Shopee sai.',
      d:'Có thể có mùa vụ, nhưng Zalo cũng chịu cùng mùa vụ; không giải thích được vì sao chỉ Shopee bị bỏ qua.'} },
  ]},

/* ------------------------------------------------------------------ 06 */
{ id:'B:dl09-06', skill:'measure', read:'7 phút', t:'Cột này cao gấp ba cột kia — thật vậy không?',
  situation:'Trong buổi họp, đội agency chiếu biểu đồ cột so sánh tỉ lệ nhớ thương hiệu trước và sau chiến dịch của một hãng bánh. Cột "sau" cao gần gấp ba cột "trước". Sếp khen: "Chiến dịch hiệu quả quá!". Bạn nhìn kỹ: trục dọc bắt đầu từ 40%, cột trước là 44%, cột sau là 52%.',
  concept:{ name:'Biểu đồ gây hiểu lầm vì trục không bắt đầu từ 0',
    body:'Với <b>biểu đồ cột</b>, mắt người so chiều cao cột. Nếu trục dọc cắt ở 40% thay vì 0, phần thấy được chỉ là phần trên 40%, nên chênh lệch nhỏ bị phóng to nhiều lần. Luật: biểu đồ cột phải bắt đầu từ 0. Biểu đồ đường thì có thể cắt trục để thấy xu hướng, nhưng phải ghi rõ mốc trục. Các bẫy khác: trục hai bên với hai thang đo khác nhau, chọn khung thời gian ngắn để giấu xu hướng dài.' },
  example:'Tính lại: phần thấy được trên trục là 44 − 40 = 4 và 52 − 40 = 12, nên cột sau trông cao gấp 3. Thực tế 52 ÷ 44 ≈ 1,18, tức cao hơn khoảng 18%, hay tăng 8 điểm phần trăm. Vẫn là kết quả tốt, nhưng khác xa "gấp ba". Bạn đề nghị vẽ lại từ 0 và ghi thẳng con số trên đầu cột. Hai bẫy còn lại cùng cơ chế: doanh thu 1,2 tỉ và chi phí 90 triệu vẽ chung một trục thì hai đường có thể chạm nhau, dù 90 triệu chỉ bằng 7,5% của 1,2 tỉ; ba tháng "tăng đều" có thể chỉ là hồi phục sau chín tháng giảm.',
  takeaway:'Biểu đồ cột phải bắt đầu từ 0; kiểm tra trục trước khi tin độ cao.',
  apply:'Mở biểu đồ cột gần nhất bạn làm, kiểm tra trục dọc bắt đầu từ đâu. Nếu không phải 0, vẽ lại và so cảm giác.',
  mistakes:['Để phần mềm tự chọn trục, nó thường cắt trục để "vừa khung".','Tin độ cao cột mà không đọc con số trên trục.'],
  q:[
  { type:'mcq', stem:'Biểu đồ cột có trục dọc bắt đầu từ 40%, cột A là 44%, cột B là 52%. Mắt người xem sẽ thấy gì?',
    options:[{k:'a',t:'Cột B cao hơn cột A khoảng 18%, đúng như chênh lệch thật'},{k:'b',t:'Hai cột gần bằng nhau vì chỉ chênh 8 điểm'},
             {k:'c',t:'Cột B trông cao gấp khoảng 3 lần cột A'},{k:'d',t:'Cột A trông cao hơn vì nằm bên trái, được nhìn thấy trước'}],
    answer:'c', why:{a:'Đó là chênh lệch thật, nhưng trục bị cắt nên mắt không thấy như vậy.',
      b:'Trục bị cắt phóng to chênh lệch chứ không làm nhỏ đi.',
      c:'Đúng. Phần thấy được là 4 và 12, nên cột B trông gấp 3.',
      d:'Vị trí trái phải không đổi chiều cao cảm nhận.'} },
  { type:'mcq', stem:'Agency chiếu biểu đồ cắt trục ngay trong họp và sếp đang khen. Bạn làm gì?',
    options:[{k:'a',t:'Nói nhẹ: con số thật là 44% lên 52%, tăng 8 điểm; xin vẽ lại từ 0'},{k:'b',t:'Im lặng để không làm mất vui, sau đó nhắn riêng agency'},
             {k:'c',t:'Tố cáo agency cố tình lừa dối, đề nghị đổi agency'},{k:'d',t:'Đồng tình với sếp vì dù sao kết quả cũng tăng, không cần phải làm lớn chuyện'}],
    answer:'a', why:{a:'Đúng. Sửa hiểu lầm ngay bằng số thật, giọng trung tính, và vẫn công nhận kết quả tăng.',
      b:'Sếp có thể quyết ngân sách dựa trên ấn tượng sai ngay trong buổi họp.',
      c:'Có thể chỉ là mặc định phần mềm; buộc tội khi chưa rõ làm hỏng quan hệ.',
      d:'Tăng 18% và tăng gấp 3 dẫn tới quyết định ngân sách rất khác nhau.'} },
  { type:'calc', stem:'Cột A là 44%, cột B là 52%. Mức tăng thực tế của B so với A là bao nhiêu phần trăm? (làm tròn 1 chữ số thập phân)',
    unit:'%', ans:18.2, tol:0.2, wrong:[[8,'NHAM_DIEM_PHAN_TRAM'],[15.4,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Chênh lệch = 52 − 44 = 8 điểm phần trăm.','Tăng tương đối = 8 ÷ 44 (số gốc là cột A) ≈ <b>18,2%</b>, không phải "gấp ba".'] },
  { type:'mcq', stem:'Biểu đồ đường giá cổ phiếu dao động 95–105 nghìn, trục dọc cắt từ 90 đến 110 nghìn. Có nên sửa trục về 0 không?',
    options:[{k:'a',t:'Có, vì mọi loại biểu đồ đều phải bắt đầu từ 0, nếu không là gây hiểu lầm'},{k:'b',t:'Không bắt buộc: biểu đồ đường so độ dốc, miễn ghi rõ mốc trục và nói dao động chỉ ±5%'},
             {k:'c',t:'Không cần, và nên bỏ luôn các mốc trục để biểu đồ nhìn gọn hơn'},{k:'d',t:'Có, vì người xem không chuyên sẽ luôn đọc sai biểu đồ đã cắt trục'}],
    answer:'b', why:{a:'Luật trục từ 0 áp dụng cho biểu đồ cột vì mắt so chiều cao cột; biểu đồ đường so độ dốc nên cắt trục được.',
      b:'Đúng. Cắt trục giúp thấy xu hướng, nhưng phải ghi mốc và nói rõ biên độ thật để không bị đọc thành biến động lớn.',
      c:'Bỏ mốc thì người xem không biết dao động chỉ khoảng 10%; cắt trục chỉ chấp nhận được khi mốc hiện rõ.',
      d:'Người xem đọc đúng được nếu mốc trục hiện rõ; vấn đề nằm ở cách vẽ, không ở người xem.'} },
  { type:'mcq', stem:'Tình huống mới: một biểu đồ có hai trục dọc, bên trái là doanh thu (tỉ đồng), bên phải là chi phí (triệu đồng). Hai đường cắt nhau ở tháng 6. Người xem dễ hiểu sai gì?',
    options:[{k:'a',t:'Tưởng doanh thu tính theo triệu vì chỉ đọc trục phải'},{k:'b',t:'Tưởng tháng 6 là tháng doanh thu cao nhất trong năm'},
             {k:'c',t:'Tưởng số liệu tháng 6 bị thiếu nên hai đường gặp nhau'},{k:'d',t:'Tưởng tháng 6 chi phí bằng doanh thu, tức hoà vốn'}],
    answer:'d', why:{a:'Có thể xảy ra nhưng không phải hiểu lầm chính mà điểm cắt gây ra.',
      b:'Điểm cắt không cho biết đỉnh của đường nào.',
      c:'Hai đường gặp nhau không gợi ý thiếu số liệu.',
      d:'Đúng. Hai thang đo khác nhau nên điểm cắt không có nghĩa gì, nhưng mắt vẫn đọc là "bằng nhau".'} },
  { type:'mcq', stem:'Cách nào an toàn nhất để tránh hiểu lầm khi trình bày biểu đồ cột cho sếp?',
    options:[{k:'a',t:'Dùng hiệu ứng 3D để cột trông nổi bật và dễ nhìn hơn'},{k:'b',t:'Cắt trục để phần chênh lệch nổi rõ, người xem dễ thấy'},
             {k:'c',t:'Trục từ 0 và ghi con số ngay trên đầu mỗi cột'},{k:'d',t:'Bỏ trục dọc đi cho gọn, chỉ giữ tên các cột'}],
    answer:'c', why:{a:'Hiệu ứng 3D làm méo chiều cao cảm nhận.',
      b:'Đó chính là cách gây hiểu lầm.',
      c:'Đúng. Chiều cao trung thực, con số rõ ràng, không phải đoán.',
      d:'Bỏ trục mà không ghi số thì người xem không biết độ lớn thật.'} },
  { type:'mcq', stem:'Biểu đồ chỉ hiển thị doanh số 3 tháng gần nhất, cho thấy tăng đều. Câu hỏi nào nên đặt ra trước khi kết luận?',
    options:[{k:'a',t:'Biểu đồ đã dùng đúng bảng màu và font chữ của thương hiệu chưa'},{k:'b',t:'12 tháng trước đó ra sao, 3 tháng này có phải hồi phục sau giảm'},
             {k:'c',t:'Ai là người đã vẽ biểu đồ này và vẽ bằng công cụ gì'},{k:'d',t:'Có thể đổi sang biểu đồ tròn cho đẹp hơn không'}],
    answer:'b', why:{a:'Màu sắc không ảnh hưởng tới kết luận.',
      b:'Đúng. Khung thời gian ngắn có thể giấu xu hướng dài hạn đi xuống.',
      c:'Người vẽ không đổi được dữ liệu; khung thời gian mới đổi.',
      d:'Biểu đồ tròn không hợp với dữ liệu theo thời gian.'} },
  ]},

/* ------------------------------------------------------------------ 07 */
{ id:'B:dl09-07', skill:'measure', read:'7 phút', t:'Con số này chắc tới đâu — và bạn có nói ra không?',
  situation:'Quân khảo sát 80 khách hàng của một chuỗi cà phê về mẫu ly mới: 55% thích mẫu mới. Anh báo sếp: "Khách thích mẫu mới." Sếp duyệt in 200.000 ly. Sau khi ra mắt, phản hồi chia đôi. Sếp hỏi: "Sao em nói khách thích?". Nhìn lại, 80 người là mẫu nhỏ và phần lớn là khách ở một cửa hàng.',
  concept:{ name:'Nói kèm độ chắc chắn',
    body:'Mỗi con số có một độ chắc chắn, phụ thuộc <b>cỡ mẫu</b>, <b>ai được hỏi</b> và <b>cách đo</b>. Quy tắc nhẩm: với mẫu ngẫu nhiên, sai số ở mức tin cậy 95% xấp xỉ 1/√n. Mẫu 80 người cho ±11 điểm, nên 55% có thể nằm từ 44% đến 66%; muốn giảm một nửa sai số phải tăng mẫu gấp bốn. Nhưng ±11 là mức tối thiểu: mẫu không ngẫu nhiên (cùng một cửa hàng) còn lệch hơn nữa và công thức không đo được phần lệch đó. Khi báo cáo, nói rõ ba mức: <b>chắc</b> (đủ để quyết), <b>tín hiệu</b> (đáng thử tiếp), <b>chưa rõ</b> (cần thêm dữ liệu).' },
  example:'Quân lẽ ra nên nói: "Khoảng 55% trong 80 khách ở cửa hàng Láng Hạ thích mẫu mới. Mẫu nhỏ và chỉ một cửa hàng, nên thật ra có thể từ khoảng 44% đến 66%, và vì chỉ một cửa hàng nên còn lệch hơn thế, chưa chắc đa số thích. Em đề xuất in thử 20.000 ly cho 5 cửa hàng trước." Cùng con số, nhưng quyết định ít rủi ro hơn nhiều.',
  takeaway:'Con số đi kèm mức chắc chắn: chắc, tín hiệu, hay chưa rõ — và quyết định tương xứng.',
  apply:'Chọn một kết luận bạn sắp báo cáo. Viết thêm một câu: con số dựa trên bao nhiêu người, ai, và nên xếp vào mức chắc, tín hiệu hay chưa rõ.',
  mistakes:['Báo tỉ lệ từ mẫu nhỏ như sự thật chắc chắn.','Giấu giới hạn của số liệu vì sợ bị đánh giá là không chắc chắn.'],
  q:[
  { type:'mcq', stem:'55% của 80 khách thích mẫu ly mới. Kết luận nào thận trọng và đúng nhất?',
    options:[{k:'a',t:'Đa số khách hàng của chuỗi đều thích mẫu ly mới'},{k:'b',t:'Khách hàng không thích mẫu mới vì 45% còn lại chiếm gần một nửa'},
             {k:'c',t:'Tín hiệu hơi nghiêng về mẫu mới, nhưng mẫu nhỏ nên chưa chắc'},{k:'d',t:'Chưa dùng được vì mẫu nhỏ thì không đáng tin chút nào'}],
    answer:'c', why:{a:'55% với mẫu nhỏ có thể dao động xuống dưới 50%; chưa đủ để nói đa số.',
      b:'Kết luận ngược cũng không có căn cứ.',
      c:'Đúng. Gọi đúng tên mức độ chắc chắn: tín hiệu, chưa phải kết luận.',
      d:'Mẫu nhỏ vẫn cho tín hiệu kèm khoảng sai số rõ ràng; bỏ hẳn là vứt dữ liệu thay vì nói đúng mức chắc.'} },
  { type:'mcq', stem:'Bạn có kết quả khảo sát mẫu nhỏ và sếp cần quyết định in 200.000 ly. Bạn đề xuất gì?',
    options:[{k:'a',t:'In 200.000 ly ngay vì khảo sát cho thấy phần đông khách hàng đã thích'},{k:'b',t:'Nói rõ số chỉ là tín hiệu, đề xuất in thử ít ở vài cửa hàng'},
             {k:'c',t:'Huỷ mẫu mới vì 45% khách chưa thích'},{k:'d',t:'Chỉ báo 55% thích, bỏ qua cỡ mẫu cho gọn'}],
    answer:'b', why:{a:'Quyết định lớn trên tín hiệu yếu là rủi ro không cần thiết.',
      b:'Đúng. Mức chắc chắn thấp thì bước đi nhỏ, rồi mở rộng khi có thêm bằng chứng.',
      c:'Tín hiệu hơi tích cực vẫn đáng thử; huỷ là bỏ lỡ.',
      d:'Giấu giới hạn khiến sếp chịu rủi ro mà không biết.'} },
  { type:'calc', stem:'Quân khảo sát lại 320 khách chọn ngẫu nhiên trong toàn chuỗi. Dùng quy tắc nhẩm sai số ≈ 1/√n (n=80 cho ±11 điểm), sai số mới xấp xỉ bao nhiêu điểm phần trăm?',
    unit:'điểm %', ans:5.6, tol:0.3, wrong:[[2.75,'SAI_TINH_TOAN'],[11,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Sai số tỉ lệ nghịch với căn bậc hai của n, không phải với n: 320 gấp 4 lần 80 nên sai số chỉ giảm một nửa.','1/√320 ≈ 0,056, tức <b>≈ 5,6 điểm</b> (11 ÷ 2 ≈ 5,5). Muốn hẹp hơn nữa phải tăng mẫu rất nhiều.'] },
  { type:'mcq', stem:'Ngoài cỡ mẫu, điều gì khiến kết quả khảo sát của Quân kém chắc chắn?',
    options:[{k:'a',t:'Phần lớn người được hỏi ở cùng một cửa hàng'},{k:'b',t:'Khảo sát được thực hiện vào buổi sáng thay vì buổi tối'},
             {k:'c',t:'Câu hỏi khảo sát có dùng từ "thích"'},{k:'d',t:'Kết quả 55% là số lẻ, khó làm tròn cho đẹp khi báo cáo'}],
    answer:'a', why:{a:'Đúng. Khách một cửa hàng có thể khác khách toàn chuỗi; mẫu không đại diện.',
      b:'Giờ khảo sát có thể ảnh hưởng nhẹ, nhưng không bằng việc cả mẫu từ một điểm.',
      c:'Dùng từ "thích" không phải vấn đề chính.',
      d:'Số lẻ không liên quan tới độ chắc chắn.'} },
  { type:'mcq', stem:'Tình huống mới: A/B test trang đích cho thấy bản B chuyển đổi tốt hơn 0,3 điểm, nhưng mỗi bản mới có 400 lượt truy cập. Bạn báo cáo thế nào?',
    options:[{k:'a',t:'"Bản B tốt hơn 0,3 điểm, đề xuất chuyển lưu lượng sang B"'},{k:'b',t:'"Bản A và B như nhau, test này thất bại và không cần chạy tiếp"'},
             {k:'c',t:'"B nhỉnh hơn nhưng quá ít lượt để chắc; đề xuất chạy thêm"'},{k:'d',t:'Chưa báo gì cho sếp cho tới khi test kết thúc'}],
    answer:'c', why:{a:'Với 400 lượt mỗi bản, tỉ lệ cỡ vài phần trăm có sai số khoảng ±2 điểm, lớn gấp nhiều lần chênh 0,3: rất dễ là dao động ngẫu nhiên.',
      b:'Nói "như nhau" cũng là kết luận quá sớm; test chưa đủ dữ liệu, không phải thất bại.',
      c:'Đúng. Nêu kết quả, nêu mức chắc chắn, đề xuất bước tiếp.',
      d:'Sếp nên biết tiến độ; chỉ cần đặt đúng kỳ vọng.'} },
  { type:'mcq', stem:'Vì sao nói rõ giới hạn của số liệu lại giúp tăng uy tín của bạn?',
    options:[{k:'a',t:'Vì sếp thích nhân viên khiêm tốn, hay tự nhận thiếu sót'},{k:'b',t:'Vì khi kết quả lệch, sếp biết bạn đã cảnh báo, không bị bất ngờ'},
             {k:'c',t:'Vì nói giới hạn giúp tránh bị quy trách nhiệm khi kết quả lệch'},{k:'d',t:'Vì báo cáo dài hơn thì trông chuyên nghiệp hơn'}],
    answer:'b', why:{a:'Không phải chuyện thái độ; là chuyện dự báo đúng rủi ro.',
      b:'Đúng. Người nói đúng mức chắc chắn được tin hơn khi họ nói "chắc".',
      c:'Mục đích là giúp chọn mức rủi ro, không phải né trách nhiệm.',
      d:'Độ dài không tạo uy tín.'} },
  { type:'mcq', stem:'Số nào dưới đây nên được xếp vào mức "chắc" khi báo cáo?',
    options:[{k:'a',t:'Tỉ lệ thích sản phẩm tính từ 30 bình luận dưới bài đăng trên fanpage'},{k:'b',t:'Dự báo doanh thu Tết dựa trên cảm nhận của đội bán hàng qua nhiều năm'},
             {k:'c',t:'Kết quả A/B test chạy 2 ngày với 200 lượt truy cập mỗi bản'},{k:'d',t:'Doanh thu tháng trước cộng từ toàn bộ hoá đơn trong hệ thống bán hàng'}],
    answer:'d', why:{a:'Người bình luận là nhóm tự chọn, không đại diện.',
      b:'Cảm nhận có giá trị nhưng là ước đoán, không phải số đo.',
      c:'Quá ngắn và quá ít lượt.',
      d:'Đúng. Là toàn bộ giao dịch chứ không phải mẫu nên không có sai số lấy mẫu; vẫn nên rà lỗi nhập.'} },
  ]},

/* ------------------------------------------------------------------ 08 */
{ id:'B:dl09-08', skill:'comm', read:'7 phút', t:'Số đã đúng, sếp vẫn hỏi "Vậy thì sao?"',
  situation:'Nga báo cáo: "Tỉ lệ khách bỏ giỏ hàng trên website tháng này là 72%, tăng từ 65% tháng trước." Sếp gật đầu, rồi hỏi: "Vậy thì sao? Mình mất bao nhiêu tiền, và em định làm gì?". Nga không trả lời được, vì cô chưa nghĩ tới bước đó.',
  concept:{ name:'Thang "vậy thì sao": số → ý nghĩa → hành động',
    body:'Một con số chỉ xong khi đi đủ ba bậc. <b>Số:</b> điều gì đã xảy ra. <b>Ý nghĩa:</b> nó ảnh hưởng tới tiền, khách, hay mục tiêu thế nào, tốt nhất quy ra tiền. <b>Hành động:</b> bạn đề xuất làm gì, cần gì từ người nghe. Trước khi đưa một con số vào báo cáo, tự hỏi "vậy thì sao?" cho tới khi câu trả lời là một việc cụ thể. Nếu không có câu trả lời nào, con số đó có lẽ không cần nằm trong báo cáo.' },
  example:'Nga đi đủ ba bậc. Số: bỏ giỏ tăng từ 65% lên 72%. Ý nghĩa: mỗi tháng có 4.000 giỏ hàng, giá trị trung bình 400 nghìn; 7 điểm tăng thêm tương đương 280 giỏ, trị giá khoảng 112 triệu. Đó là <b>mức trần</b>: không phải giỏ nào cũng sẽ thành đơn, và mất doanh thu chưa phải mất lãi. Giả định minh hoạ: nếu 1/4 số giỏ đó lẽ ra thành đơn và biên đóng góp 30%, lãi mất thật khoảng 280 × 25% × 400 nghìn × 30% ≈ 8,4 triệu/tháng; con số này mới là mức trần cho chi phí của giải pháp. Hành động: phí ship mới áp từ đầu tháng là nghi phạm chính; em đề xuất thử miễn ship đơn trên 300 nghìn trong 2 tuần, đo lại cả tỉ lệ bỏ giỏ lẫn lãi sau chi phí ship.',
  takeaway:'Mỗi con số phải trả lời được "vậy thì sao?" bằng tiền và bằng một việc cần làm.',
  apply:'Chọn một con số trong báo cáo của bạn. Viết ba dòng: số, ý nghĩa (quy ra tiền nếu được), hành động đề xuất.',
  mistakes:['Dừng ở việc mô tả số tăng hay giảm.','Nêu hành động nhưng không nối với con số, nên sếp không thấy vì sao phải làm.'],
  q:[
  { type:'mcq', stem:'Bạn báo "tỉ lệ bỏ giỏ tăng từ 65% lên 72%". Sếp hỏi "vậy thì sao?". Sếp đang cần gì?',
    options:[{k:'a',t:'Định nghĩa chính xác của tỉ lệ bỏ giỏ hàng'},{k:'b',t:'Ảnh hưởng tới doanh thu và việc bạn định làm'},
             {k:'c',t:'Số liệu bỏ giỏ của các đối thủ trong cùng ngành để so sánh'},{k:'d',t:'Biểu đồ tỉ lệ bỏ giỏ của 12 tháng qua'}],
    answer:'b', why:{a:'Sếp có thể cần, nhưng "vậy thì sao" hỏi về hệ quả.',
      b:'Đúng. Sếp muốn biết con số này đáng lo bao nhiêu và cần làm gì.',
      c:'Mốc so sánh có ích nhưng chưa trả lời câu hỏi hệ quả.',
      d:'Thêm dữ liệu không thay được phần ý nghĩa và hành động.'} },
  { type:'mcq', stem:'Bạn chỉ có một câu để trả lời "vậy thì sao?". Bạn chọn câu nào?',
    options:[{k:'a',t:'"Tỉ lệ này cao hơn mức trung bình mà em đọc được trên mạng"'},{k:'b',t:'"Đây là xu hướng chung của thương mại điện tử năm nay, các bên khác cũng gặp"'},
             {k:'c',t:'"Em sẽ theo dõi thêm và báo lại anh sau"'},{k:'d',t:'"Giỏ bỏ thêm trị giá tới ~110 triệu/tháng; em đề xuất thử miễn ship"'}],
    answer:'d', why:{a:'So với số không rõ nguồn không giúp quyết định.',
      b:'Đổ cho xu hướng chung là né câu hỏi; vẫn chưa nói mình làm gì.',
      c:'Hứa theo dõi mà không có hành động là trì hoãn.',
      d:'Đúng. Quy ra tiền và có hành động cụ thể trong một câu; nhớ nói rõ đây là mức trần giá trị giỏ, lãi mất thật nhỏ hơn nhiều.'} },
  { type:'calc', stem:'Mỗi tháng có 4.000 giỏ hàng, giá trị trung bình 400 nghìn. Tỉ lệ bỏ giỏ tăng từ 65% lên 72%. Giá trị giỏ bị bỏ thêm mỗi tháng (mức trần của doanh thu bị bỏ lỡ) là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:112, tol:1, wrong:[[1152,'SAI_MAU_SO'],[11.2,'NHAM_DIEM_PHAN_TRAM']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Tăng 7 điểm phần trăm: 4.000 × 7% = 280 giỏ bỏ thêm.','280 × 400 nghìn = 112.000 nghìn = <b>112 triệu</b>. Đây là mức trần: chỉ một phần giỏ bỏ lẽ ra thành đơn, và lãi mất còn nhỏ hơn doanh thu mất.'] },
  { type:'mcq', stem:'Trong ba bậc "số → ý nghĩa → hành động", bậc ý nghĩa nên được diễn đạt bằng gì nếu có thể?',
    options:[{k:'a',t:'Bằng tiền: doanh thu, lợi nhuận hoặc chi phí'},{k:'b',t:'Bằng từ ngữ mạnh để gây chú ý như "báo động", "nghiêm trọng"'},
             {k:'c',t:'Bằng thêm nhiều chỉ số phụ khác để làm rõ hơn'},{k:'d',t:'Bằng so sánh với trung bình ngành đọc được trên báo'}],
    answer:'a', why:{a:'Đúng. Tiền là đơn vị sếp dùng để so các việc với nhau.',
      b:'Từ mạnh không cho biết mức độ; số tiền thì có.',
      c:'Thêm chỉ số làm rối, không làm rõ ý nghĩa.',
      d:'So ngành là mốc, không phải hệ quả với chính doanh nghiệp.'} },
  { type:'mcq', stem:'Tình huống mới: bạn định đưa vào báo cáo "lượt theo dõi TikTok tăng 3.000". Tự hỏi "vậy thì sao?" mà không ra được hệ quả gì. Bạn làm gì?',
    options:[{k:'a',t:'Vẫn giữ ở đầu báo cáo vì con số tăng trông tích cực'},{k:'b',t:'Bịa thêm một hệ quả cho có, ví dụ "sẽ tăng doanh thu sau này"'},
             {k:'c',t:'Chuyển xuống phụ lục hoặc bỏ, dành chỗ cho số có hệ quả'},{k:'d',t:'Tăng thêm cỡ chữ cho con số đó để sếp chú ý'}],
    answer:'c', why:{a:'Con số không dẫn tới quyết định chỉ làm loãng báo cáo.',
      b:'Gắn hệ quả không có căn cứ là tự làm mất uy tín.',
      c:'Đúng. Không trả lời được "vậy thì sao" thì con số không xứng chỗ chính.',
      d:'Nhấn mạnh con số không có hệ quả còn làm lệch trọng tâm hơn.'} },
  { type:'mcq', stem:'Nga đề xuất "thử miễn ship đơn trên 300 nghìn trong 2 tuần". Vì sao đề xuất có thời hạn và ngưỡng rõ ràng lại tốt hơn "sẽ cải thiện trải nghiệm"?',
    options:[{k:'a',t:'Vì câu ngắn hơn, dễ đưa lên slide'},{k:'b',t:'Vì có thể đo được và sếp biết chính xác mình đang duyệt cái gì'},
             {k:'c',t:'Vì miễn ship là cách giảm bỏ giỏ phổ biến nhất ở shop online'},{k:'d',t:'Vì đơn trên 300 nghìn thường có lãi đủ bù phí ship'}],
    answer:'b', why:{a:'Độ ngắn không phải lý do chính.',
      b:'Đúng. Ngưỡng, thời hạn rõ thì chi phí rõ, kết quả đo được.',
      c:'Phổ biến không có nghĩa là hợp với shop này; đây vẫn là giả thuyết cần thử.',
      d:'Có thể đúng nhưng chưa ai kiểm; lợi thế của đề xuất là đo được và rõ phạm vi duyệt.'} },
  { type:'mcq', stem:'Câu nào đi đủ cả ba bậc "số → ý nghĩa → hành động"?',
    options:[{k:'a',t:'"CTR giảm từ 2% xuống 1,4% trong tháng này"'},{k:'b',t:'"CTR giảm mạnh, đây là một tín hiệu đáng lo ngại cho cả đội"'},
             {k:'c',t:'"Em sẽ làm mẫu quảng cáo mới trong tuần sau"'},{k:'d',t:'"CTR giảm 30%, chi phí mỗi đơn tăng 8 triệu/tháng; em thay mẫu"'}],
    answer:'d', why:{a:'Chỉ có số.',
      b:'Có cảm nhận ý nghĩa nhưng không quy ra tiền, không có hành động.',
      c:'Có hành động nhưng không nối với số nào.',
      d:'Đúng. Số, hệ quả bằng tiền, và việc sẽ làm.'} },
  ]},

/* ------------------------------------------------------------------ 09 */
{ id:'B:dl09-09', skill:'comm', read:'6 phút', t:'Báo cáo tuần dài 3 trang — ai đọc?',
  situation:'Mỗi thứ Sáu, Phúc gửi sếp báo cáo tuần 3 trang: bảng số từng kênh, ảnh chụp dashboard, danh sách việc đã làm. Sếp thừa nhận chỉ đọc lướt dòng đầu. Tuần trước, một vấn đề quan trọng, kho sắp hết mã sản phẩm bán chạy, nằm ở trang 3 và không ai thấy cho tới khi hết hàng thật.',
  concept:{ name:'Báo cáo tuần 5 dòng',
    body:'Một báo cáo tuần sếp đọc được trong 1 phút có 5 dòng cố định: <b>1. Kết quả chính</b> so với mục tiêu tuần. <b>2. Điều tốt</b> và vì sao. <b>3. Điều xấu hoặc rủi ro</b>. <b>4. Việc tuần tới</b>. <b>5. Cần sếp hỗ trợ/quyết gì</b>. Dòng 3 chỉ chứa 1–2 rủi ro: chọn việc có tác động lớn nhất tới tiền hoặc khách và còn kịp xử lý, không phải việc dễ thấy nhất trên dashboard. Bảng số chi tiết gắn kèm cho ai muốn đào sâu.' },
  example:'Phúc viết lại: (1) Doanh thu tuần 312 triệu, đạt 104% mục tiêu 300 triệu. (2) Combo quà Trung thu bán 640 bộ, gấp đôi dự kiến. (3) Rủi ro: mã nước hoa hồng còn hàng khoảng 5 ngày. (4) Tuần tới: đẩy combo trên Shopee, giảm quảng cáo mã sắp hết. (5) Cần anh duyệt nhập gấp 1.500 chai trước thứ Tư. Rủi ro hết hàng giờ nằm ở dòng 3.',
  takeaway:'Báo cáo tuần: 5 dòng cố định, rủi ro và việc cần quyết không bao giờ nằm ở trang 3.',
  points:["Khung cố định giúp sếp biết đi đâu để tìm gì mỗi tuần. Vị trí quen thuộc làm việc đọc nhanh hơn, và thiếu một dòng cũng thành tín hiệu đáng hỏi.","Giới hạn một đến hai rủi ro buộc người viết xếp hạng. Danh sách mười rủi ro ngang nhau thực chất là không rủi ro nào được ưu tiên, nên chẳng ai hành động.","Dòng cần quyết có hạn chót đi kèm biến báo cáo thành lời đề nghị. Sếp thấy cái giá của việc chờ, như hàng về trước thứ Tư, nên dễ ra quyết định hơn."],
  counter:"Giả sử tuần này đội chuẩn bị đợt lễ lớn với hàng chục đầu việc phụ thuộc nhau và sếp muốn thấy tiến độ từng việc. Năm dòng sẽ nén quá mức và che mất chỗ đang trễ. Dấu hiệu nhận ra: sếp liên tục hỏi lại chi tiết sau khi đọc. Khi đó giữ năm dòng ở đầu nhưng đính kèm một bảng tiến độ ngắn, đánh dấu việc trễ.",
  deeper:"Người làm nghề đánh đổi giữa độ ngắn và độ đủ: báo cáo ngắn dễ đọc nhưng buộc người viết gánh việc chọn lọc, và chọn sai thì sếp mất thông tin. Họ giảm rủi ro đó bằng cách đính kèm chi tiết cho ai cần. Tín hiệu nên theo là sếp có hành động sau báo cáo hay không: nếu không ai phản hồi nhiều tuần, báo cáo đang bị đọc lướt. Khái niệm kề cận là cảnh báo sớm. Phép kiểm tra trong tuần: viết báo cáo tuần này đúng 5 dòng, mỗi dòng không quá 25 chữ, rồi hỏi sếp có hiểu mình cần gì không.",
  apply:'Viết báo cáo tuần này của bạn đúng 5 dòng theo khung trên, mỗi dòng không quá 25 chữ.',
  mistakes:['Liệt kê việc đã làm thay vì kết quả.','Để rủi ro và yêu cầu hỗ trợ ở cuối, sau hàng chục dòng số.'],
  q:[
  { type:'mcq', stem:'Vấn đề hết hàng không ai thấy dù đã có trong báo cáo tuần. Nguyên nhân chính là gì?',
    options:[{k:'a',t:'Sếp không làm tròn trách nhiệm đọc hết báo cáo'},{k:'b',t:'Phúc chưa có đủ dữ liệu tồn kho chính xác để cảnh báo sớm'},
             {k:'c',t:'Báo cáo được gửi vào thứ Sáu, sếp đã bận'},{k:'d',t:'Báo cáo dài, không có vị trí cố định cho rủi ro'}],
    answer:'d', why:{a:'Người viết phải thiết kế báo cáo cho cách người đọc thực sự đọc.',
      b:'Phúc đã có số; vấn đề là nó bị chôn ở trang 3.',
      c:'Ngày gửi không phải lý do chính.',
      d:'Đúng. Rủi ro nằm lẫn giữa các bảng số nên không nổi lên.'} },
  { type:'mcq', stem:'Bạn chuyển sang báo cáo 5 dòng. Còn bảng số chi tiết và ảnh dashboard, bạn làm gì?',
    options:[{k:'a',t:'Bỏ hết để báo cáo gọn, ai hỏi thì mới làm lại'},{k:'b',t:'Đặt chúng lên trước 5 dòng để sếp thấy đội làm việc chăm chỉ'},
             {k:'c',t:'Đính kèm hoặc để link bên dưới 5 dòng cho ai muốn xem sâu'},{k:'d',t:'Tách ra gửi bằng một email khác vào đầu tuần sau cho đỡ dài'}],
    answer:'c', why:{a:'Người cần chi tiết vẫn phải có chỗ tra cứu; làm lại mỗi lần tốn công.',
      b:'Đặt lên trước là quay lại vấn đề cũ.',
      c:'Đúng. 5 dòng cho quyết định, phụ lục cho tra cứu.',
      d:'Tách email làm rời rạc thông tin; khó tìm lại.'} },
  { type:'mcq', stem:'Dòng 3 chỉ còn chỗ cho một rủi ro, mà tuần này có bốn sự việc. Bạn đưa sự việc nào lên dòng 3?',
    options:[{k:'a',t:'CTR banner giảm 0,3 điểm phần trăm, vẫn nằm trong mức dao động thường ngày'},{k:'b',t:'Đối tác vận chuyển báo tăng phí 15% từ tuần sau, chưa có phương án thay thế'},
             {k:'c',t:'Một bình luận chê trên fanpage được 4 lượt thích, chưa ai trả lời'},{k:'d',t:'Đội thiết kế nộp file trễ một ngày nhưng không ảnh hưởng lịch đăng bài'}],
    answer:'b', why:{a:'Con số nằm trong dao động thường ngày; nó dễ thấy trên dashboard nhưng không đổi quyết định nào.',
      b:'Đúng. Tác động trực tiếp tới chi phí, có thời hạn rõ và sếp có thể làm gì đó (đàm phán, đổi đối tác) nếu biết sớm.',
      c:'Quy mô nhỏ và xử lý được ngay bằng một câu trả lời; không cần sếp quyết.',
      d:'Đã không ảnh hưởng lịch đăng; ghi vào dòng 3 chỉ làm loãng cảnh báo thật.'} },
  { type:'mcq', stem:'Dòng nào sau đây phù hợp cho dòng 1 "Kết quả chính" của báo cáo tuần?',
    options:[{k:'a',t:'Doanh thu 312 triệu, đạt 104% mục tiêu tuần'},{k:'b',t:'Tuần này đội đã đăng 14 bài, chạy 6 mẫu quảng cáo và họp 3 buổi'},
             {k:'c',t:'Tuần này làm việc rất tích cực và hiệu quả'},{k:'d',t:'Đã hoàn thành đầy đủ các đầu việc được giao theo kế hoạch'}],
    answer:'a', why:{a:'Đúng. Kết quả, so với mục tiêu, một dòng.',
      b:'Danh sách việc làm, không phải kết quả.',
      c:'Tự đánh giá không có số.',
      d:'Hoàn thành việc không đồng nghĩa với đạt kết quả.'} },
  { type:'mcq', stem:'Tình huống mới: tuần này không có rủi ro đáng kể nào. Dòng 3 bạn viết gì?',
    options:[{k:'a',t:'Bỏ hẳn dòng 3 để báo cáo ngắn hơn, chỉ còn 4 dòng'},{k:'b',t:'"Không có rủi ro lớn; theo dõi tồn kho mã X, còn khoảng 3 tuần"'},
             {k:'c',t:'Tìm một rủi ro nhỏ nào đó và viết thật nghiêm trọng cho đủ dòng'},{k:'d',t:'Chép lại rủi ro của tuần trước cho đủ khung'}],
    answer:'b', why:{a:'Bỏ dòng làm sếp không biết là không có rủi ro hay là quên viết.',
      b:'Đúng. Nói rõ "không có" và nêu điều đang theo dõi; khung vẫn giữ nguyên.',
      c:'Phóng đại làm mất độ tin cậy của các cảnh báo thật sau này.',
      d:'Rủi ro cũ đã xử lý mà vẫn chép làm sếp hiểu sai tình hình.'} },
  { type:'calc', stem:'Mã nước hoa hồng còn 400 chai, bán 80 chai mỗi ngày, nhập mới mất 7 ngày mới về. Trong 7 ngày đó mất bao nhiêu chai doanh số vì hết hàng?',
    unit:'chai', ans:160, tol:1, wrong:[[560,'SAI_TINH_TOAN'],[400,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Nhu cầu 7 ngày = 7 × 80 = 560 chai.','Tồn kho đáp ứng được 400 chai; thiếu 560 − 400 = <b>160 chai</b>. Con số này là lý do rủi ro phải lên dòng 3 và kèm hạn chót ở dòng 5.'] },
  { type:'mcq', stem:'Một đồng nghiệp viết dòng 2 "Điều tốt": "Combo Trung thu bán chạy". Nên sửa thế nào?',
    options:[{k:'a',t:'Thêm nhiều biểu tượng cảm xúc cho nổi bật'},{k:'b',t:'Viết dài hơn, kể lại quá trình lên ý tưởng combo từ đầu tháng'},
             {k:'c',t:'Giữ nguyên, vì câu đã đủ ngắn và rõ nghĩa'},{k:'d',t:'"Combo Trung thu bán 640 bộ, gấp đôi dự kiến, nhờ quà tặng kèm"'}],
    answer:'d', why:{a:'Biểu tượng không thay được số và lý do.',
      b:'Quá trình không cần trong báo cáo 5 dòng.',
      c:'"Bán chạy" không có số, không có lý do để nhân rộng.',
      d:'Đúng. Có số, có mốc so sánh, có lý do — đủ để quyết có làm tiếp không.'} },
  ]},

/* ------------------------------------------------------------------ 10 */
{ id:'B:dl09-10', skill:'comm', read:'7 phút', t:'Sếp hỏi câu bạn chưa chuẩn bị: trả lời sao?',
  situation:'Trang trình bày kết quả chiến dịch ra mắt sữa hạt: 2.500 đơn, chi phí mỗi đơn 80 nghìn, đạt mục tiêu. Sếp hỏi liền ba câu: "Bao nhiêu phần trăm là khách mới? Nếu không chạy quảng cáo thì có bán được không? Lãi thật là bao nhiêu?". Trang chỉ trả lời được câu đầu, hai câu sau cô ấp úng và đoán bừa một con số.',
  concept:{ name:'Chuẩn bị trước câu hỏi khó',
    body:'Câu hỏi khó của sếp thường rơi vào vài nhóm quen thuộc: <b>so với cái gì</b>, <b>nhờ mình hay nhờ yếu tố khác</b> (mùa vụ, khuyến mãi, tự nhiên), <b>lãi thật sau mọi chi phí</b>, <b>có bền không</b>, và <b>nếu làm lại thì sao</b>. Trước buổi họp, viết ra 5 câu khó nhất và trả lời sẵn. Gặp câu chưa chuẩn bị: nói điều mình biết, nói rõ điều chưa biết, hẹn thời gian trả lời. Không đoán một con số cho qua chuyện.' },
  example:'Trang lẽ ra nên chuẩn bị sẵn phép tính lãi: 2.500 đơn, giá bán 250 nghìn, lãi gộp 40% = 100 nghìn/đơn, trừ quảng cáo 80 nghìn/đơn, còn 20 nghìn/đơn, tổng khoảng 50 triệu. Với câu "nếu không chạy quảng cáo", cô có thể nói: "Em chưa có nhóm đối chứng nên chưa biết chắc; em sẽ tắt quảng cáo ở 2 tỉnh trong 2 tuần để đo và báo anh ngày 15."',
  takeaway:'Viết trước 5 câu khó nhất; câu chưa biết thì nói chưa biết và hẹn ngày trả lời.',
  points:["Câu hỏi khó của sếp lặp lại qua nhiều buổi họp vì sếp chịu trách nhiệm về tiền. Gom chúng thành vài nhóm cho phép chuẩn bị một lần, dùng nhiều lần.","Nói rõ phần chưa biết giúp sếp tin phần đã biết. Người dám nói chưa có số thì lời của họ về những con số khác được tin hơn.","Hẹn ngày trả lời biến câu hỏi hở thành một việc có chủ. Sếp rời cuộc họp biết khi nào có đáp án, thay vì mang theo một nghi ngờ."],
  counter:"Giả sử câu hỏi đến giữa buổi họp có cả khách hàng ngoài công ty, và thú nhận chưa biết trước mặt họ có thể làm giảm uy tín. Khung này cần chỉnh theo người nghe. Dấu hiệu nhận ra: người nghe không phải sếp trực tiếp mà là bên cần sự yên tâm. Khi đó trả lời ngắn phần đã biết, rồi đề nghị trao đổi riêng sau buổi họp thay vì thú nhận giữa chỗ đông.",
  deeper:"Người làm nghề coi phần hỏi đáp là một nửa của báo cáo. Đánh đổi là chuẩn bị kỹ tốn thời gian, nhưng rẻ hơn nhiều so với một con số đoán sai bị lấy làm quyết định. Tín hiệu nên theo là những câu hỏi lặp lại qua các buổi họp: câu nào sếp hỏi hai lần nghĩa là nên có sẵn trong báo cáo chính. Khái niệm kề cận là lãi thật sau các chi phí và nhóm đối chứng. Phép kiểm tra trong tuần: viết năm câu sếp khó hỏi nhất, trả lời mỗi câu trong một dòng, và đánh dấu câu nào bạn chưa có số.",
  apply:'Với báo cáo sắp tới, viết 5 câu sếp khó hỏi nhất theo 5 nhóm trên, và trả lời sẵn mỗi câu trong một dòng.',
  mistakes:['Đoán bừa một con số khi bị hỏi bất ngờ.','Chỉ chuẩn bị phần trình bày mà không chuẩn bị phần hỏi đáp.'],
  q:[
  { type:'mcq', stem:'Chiến dịch đạt mục tiêu đơn. Câu hỏi nào sếp có khả năng hỏi nhất mà người trình bày hay quên chuẩn bị?',
    options:[{k:'a',t:'Chiến dịch dùng font chữ và màu sắc gì trong thiết kế quảng cáo'},{k:'b',t:'Ai là người viết nội dung quảng cáo'},
             {k:'c',t:'Chiến dịch chạy trên những nền tảng nào'},{k:'d',t:'Sau quảng cáo và giá vốn thì lãi thật là bao nhiêu'}],
    answer:'d', why:{a:'Chi tiết thiết kế hiếm khi là mối quan tâm của người quyết ngân sách.',
      b:'Không liên quan tới hiệu quả kinh doanh.',
      c:'Thường đã có trong phần trình bày.',
      d:'Đúng. Đạt số đơn chưa chắc có lãi; đây là câu sếp gần như luôn hỏi.'} },
  { type:'mcq', stem:'Sếp hỏi "Nếu không chạy quảng cáo thì có bán được không?" và bạn chưa có dữ liệu. Bạn chọn trả lời thế nào?',
    options:[{k:'a',t:'Đưa ra một con số ước đoán cho qua, ví dụ "khoảng 30% vẫn bán được"'},{k:'b',t:'"Chưa có đối chứng nên chưa biết; em sẽ thử tắt ở 2 tỉnh và báo ngày 15"'},
             {k:'c',t:'"Khó bán được, vì phần lớn đơn hiện đến từ quảng cáo"'},{k:'d',t:'Chuyển sang nói về một chỉ số tốt khác để tránh câu hỏi'}],
    answer:'b', why:{a:'Số đoán sẽ được ghi nhớ như số thật và dùng để quyết định.',
      b:'Đúng. Nói rõ chưa biết, có kế hoạch đo, có ngày trả lời.',
      c:'Đơn đến qua quảng cáo chưa chắc là đơn nhờ quảng cáo; chưa có đối chứng thì vẫn là đoán.',
      d:'Né câu hỏi làm mất uy tín nhanh hơn thừa nhận chưa biết.'} },
  { type:'calc', stem:'Chiến dịch có 2.500 đơn, giá bán 250 nghìn/đơn, lãi gộp 40%, chi phí quảng cáo 80 nghìn/đơn. Lãi sau quảng cáo của cả chiến dịch là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:50, tol:0.5, wrong:[[250,'QUEN_TRU_CHI_PHI_QC'],[425,'ROAS_LA_LOI_NHUAN']], errors:['QUEN_TRU_CHI_PHI_QC'],
    steps:['Lãi gộp mỗi đơn = 250 × 40% = 100 nghìn.','Trừ quảng cáo: 100 − 80 = 20 nghìn/đơn.','2.500 × 20 nghìn = 50.000 nghìn = <b>50 triệu</b>.'] },
  { type:'mcq', stem:'Cách chuẩn bị hiệu quả nhất cho phần hỏi đáp là gì?',
    options:[{k:'a',t:'Viết trước 5 câu khó nhất theo các nhóm quen thuộc và trả lời sẵn'},{k:'b',t:'Học thuộc bảng số liệu chi tiết của từng kênh'},
             {k:'c',t:'Kéo dài phần trình bày để không còn thời gian cho câu hỏi của sếp'},{k:'d',t:'Nhờ đồng nghiệp trả lời thay khi gặp câu khó'}],
    answer:'a', why:{a:'Đúng. Câu hỏi khó có khuôn mẫu; chuẩn bị theo nhóm bao phủ được phần lớn.',
      b:'Thuộc số không giúp trả lời câu "nhờ mình hay nhờ yếu tố khác".',
      c:'Né hỏi đáp làm sếp nghi ngờ và hỏi lại sau, khó hơn.',
      d:'Đồng nghiệp có thể giúp, nhưng người trình bày phải nắm chính.'} },
  { type:'mcq', stem:'Tình huống mới: doanh số tháng 12 tăng 40% và sếp hỏi "Có phải nhờ mùa lễ không?". Bạn đã chuẩn bị. Câu trả lời tốt nhất là gì?',
    options:[{k:'a',t:'"Không phải đâu anh, phần tăng là nhờ chiến dịch của đội mình"'},{k:'b',t:'"Có lẽ một phần là do mùa lễ anh ạ, nhưng thật sự rất khó để tách riêng ra được"'},
             {k:'c',t:'"Cùng kỳ năm ngoái tăng 25% nhờ mùa lễ; năm nay 40%, nên phần mình thêm khoảng 15 điểm"'},{k:'d',t:'"Em không rõ lắm, để em hỏi lại agency"'}],
    answer:'c', why:{a:'Nhận hết công mà không có bằng chứng dễ bị bác bỏ.',
      b:'Nói "khó tách" khi đã có số cùng kỳ là bỏ phí sự chuẩn bị.',
      c:'Đúng. Dùng cùng kỳ làm mốc để tách phần mùa vụ và phần của chiến dịch.',
      d:'Câu này đoán trước được; không chuẩn bị là thiếu sót.'} },
  { type:'mcq', stem:'Vì sao đoán bừa một con số khi bị hỏi bất ngờ lại nguy hiểm hơn nói "em chưa biết"?',
    options:[{k:'a',t:'Vì sếp sẽ kiểm tra lại ngay lập tức trong buổi họp'},{k:'b',t:'Vì con số được nói ra sẽ được ghi nhớ và dùng để quyết định'},
             {k:'c',t:'Vì sếp sẽ nhận ra ngay đó là con số đoán bừa'},{k:'d',t:'Vì công ty có quy định cấm nêu số không có nguồn'}],
    answer:'b', why:{a:'Thường không kiểm tra ngay; chính vì vậy số sai mới đi xa.',
      b:'Đúng. Số đoán trở thành "số thật" trong đầu người nghe và dẫn quyết định sai.',
      c:'Sếp thường không nhận ra; chính vì thế số đoán bị ghi nhớ và dùng để quyết định.',
      d:'Không cần quy định; rủi ro nằm ở hệ quả của quyết định.'} },
  { type:'mcq', stem:'Câu hỏi "Kết quả này có bền không?" nên được chuẩn bị bằng dữ liệu nào?',
    options:[{k:'a',t:'Tỉ lệ khách của chiến dịch quay lại mua lần hai'},{k:'b',t:'Tổng lượt hiển thị và tiếp cận của chiến dịch'},
             {k:'c',t:'Số lượng bình luận khen trên fanpage'},{k:'d',t:'Chi phí mỗi đơn trong tuần đầu tiên của chiến dịch'}],
    answer:'a', why:{a:'Đúng. Mua lại cho biết khách ở lại hay chỉ đến vì khuyến mãi.',
      b:'Hiển thị nói về độ phủ, không nói gì về việc khách có ở lại.',
      c:'Bình luận là nhóm tự chọn, không đo được hành vi mua lại.',
      d:'Chỉ số tuần đầu là thời điểm, không phải độ bền.'} },
  ]},

]});
